CREATE TABLE IF NOT EXISTS "agriculture"."input_submission" (
    "input_submission_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "submission_code" "text" NOT NULL,
    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid",
    "submission_type" "text" NOT NULL,
    "submission_status" "text" DEFAULT 'RECEIVED'::"text" NOT NULL,
    "submitted_payload" "jsonb" NOT NULL,
    "normalised_payload" "jsonb",
    "submitted_by" "uuid",
    "request_context_id" "uuid",
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "validation_completed_at" timestamp with time zone,
    "accepted_by" "uuid",
    "accepted_at" timestamp with time zone,
    "rejection_reason" "text",
    CONSTRAINT "input_submission_final_state_consistency" CHECK (((("submission_status" = 'ACCEPTED'::"text") AND ("accepted_by" IS NOT NULL) AND ("accepted_at" IS NOT NULL)) OR ("submission_status" <> 'ACCEPTED'::"text"))),
    CONSTRAINT "input_submission_rejection_consistency" CHECK (((("submission_status" = 'REJECTED'::"text") AND ("rejection_reason" IS NOT NULL)) OR ("submission_status" <> 'REJECTED'::"text"))),
    CONSTRAINT "input_submission_submission_status_check" CHECK (("submission_status" = ANY (ARRAY['RECEIVED'::"text", 'VALIDATING'::"text", 'VALID'::"text", 'VALID_WITH_WARNINGS'::"text", 'QUARANTINED'::"text", 'REJECTED'::"text", 'ACCEPTED'::"text", 'SUPERSEDED'::"text"]))),
    CONSTRAINT "input_submission_submission_type_check" CHECK (("submission_type" = ANY (ARRAY['INGREDIENT'::"text", 'TRIAL'::"text", 'PLOT'::"text", 'APPLICATION'::"text", 'OBSERVATION'::"text", 'MEASUREMENT'::"text", 'OUTCOME'::"text", 'PHOTO_EVIDENCE'::"text", 'DISCOVERY_CANDIDATE'::"text", 'OTHER'::"text"])))
);


ALTER TABLE "agriculture"."input_submission" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_accept_validated_input"("p_input_submission_id" "uuid", "p_actor_id" "uuid") RETURNS "agriculture"."input_submission"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.input_submission; failures integer; photos integer; BEGIN
 IF p_actor_id IS NULL THEN RAISE EXCEPTION 'INPUT_ACCEPTANCE_REQUIRES_ACTOR' USING ERRCODE='23514'; END IF;
 SELECT count(*) INTO failures FROM agriculture.input_validation_event WHERE input_submission_id=p_input_submission_id AND validation_result='FAIL'; IF failures>0 THEN RAISE EXCEPTION 'INPUT_HAS_FAILED_VALIDATION_AND_CANNOT_BE_ACCEPTED' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM agriculture.input_submission WHERE input_submission_id=p_input_submission_id FOR UPDATE; IF r.input_submission_id IS NULL OR r.submission_status NOT IN ('VALID','VALID_WITH_WARNINGS') THEN RAISE EXCEPTION 'INPUT_NOT_IN_ACCEPTABLE_VALIDATED_STATE' USING ERRCODE='55000'; END IF;
 IF r.submission_type='OBSERVATION' THEN SELECT count(*) INTO photos FROM agriculture.photo_evidence WHERE input_submission_id=p_input_submission_id AND image_quality_status IN ('ACCEPTABLE','ACCEPTABLE_WITH_WARNINGS') AND context_validation_status IN ('VALIDATED','VALIDATED_WITH_WARNINGS') AND review_status IN ('APPROVED','APPROVED_WITH_WARNINGS') AND consent_usage_status IN ('APPROVED','RESTRICTED'); IF photos=0 THEN RAISE EXCEPTION 'OBSERVATION_INPUT_REQUIRES_APPROVED_USABLE_PHOTO_EVIDENCE' USING ERRCODE='23514'; END IF; END IF;
 UPDATE agriculture.input_submission SET submission_status='ACCEPTED',accepted_by=p_actor_id,accepted_at=now() WHERE input_submission_id=p_input_submission_id RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_accept_validated_input"("p_input_submission_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."trial" (
    "trial_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "trial_code" "text" NOT NULL,
    "trial_name" "text" NOT NULL,
    "formulation_version_id" "uuid",
    "organization_id" "uuid",
    "farm_id" "uuid",
    "location_id" "uuid",
    "crop_id" "uuid",
    "variety_id" "uuid",
    "problem_id" "uuid",
    "trial_objective" "text" NOT NULL,
    "protocol_summary" "text",
    "start_date" "date",
    "planned_end_date" "date",
    "actual_end_date" "date",
    "lifecycle_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "outcome_status" "text" DEFAULT 'NOT_RECORDED'::"text" NOT NULL,
    "governance_decision_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "trial_actual_date_consistency" CHECK ((("actual_end_date" IS NULL) OR ("start_date" IS NULL) OR ("actual_end_date" >= "start_date"))),
    CONSTRAINT "trial_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "trial_date_consistency" CHECK ((("planned_end_date" IS NULL) OR ("start_date" IS NULL) OR ("planned_end_date" >= "start_date"))),
    CONSTRAINT "trial_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'APPROVED'::"text", 'ACTIVE'::"text", 'PAUSED'::"text", 'COMPLETED'::"text", 'CANCELLED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "trial_outcome_status_check" CHECK (("outcome_status" = ANY (ARRAY['NOT_RECORDED'::"text", 'PARTIAL'::"text", 'RECORDED'::"text", 'REVIEWED'::"text"])))
);


ALTER TABLE "agriculture"."trial" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_activate_trial"("p_trial_id" "uuid", "p_governance_decision_id" "uuid", "p_actor_id" "uuid") RETURNS "agriculture"."trial"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
declare
  r agriculture.trial;
  ds text;
  fv_ready text;
  fv_status text;
  plot_count integer;
  primary_protocol_count integer;
begin
  select decision_status into ds from agriculture.governance_decision where decision_id=p_governance_decision_id;
  if ds<>'APPROVED' then
    raise exception 'TRIAL_ACTIVATION_REQUIRES_APPROVED_GOVERNANCE_DECISION' using errcode='23514';
  end if;

  select * into r from agriculture.trial where trial_id=p_trial_id for update;
  if r.trial_id is null then raise exception 'TRIAL_NOT_FOUND' using errcode='P0002'; end if;
  if r.lifecycle_status not in ('DRAFT','UNDER_REVIEW','APPROVED') then
    raise exception 'TRIAL_NOT_ELIGIBLE_FOR_ACTIVATION_FROM_CURRENT_LIFECYCLE: %',r.lifecycle_status using errcode='55000';
  end if;

  if r.formulation_version_id is not null then
    select trial_readiness,lifecycle_status into fv_ready,fv_status
    from agriculture.formulation_version where formulation_version_id=r.formulation_version_id;
    if fv_ready<>'READY_FOR_TRIAL' or fv_status<>'APPROVED' then
      raise exception 'TRIAL_FORMULATION_NOT_APPROVED_AND_READY' using errcode='23514';
    end if;
  end if;

  select count(*) into plot_count from agriculture.plot where trial_id=p_trial_id and lifecycle_status='ACTIVE';
  if plot_count=0 then raise exception 'TRIAL_REQUIRES_AT_LEAST_ONE_ACTIVE_PLOT' using errcode='23514'; end if;

  select count(*) into primary_protocol_count
  from agriculture.trial_protocol_binding b
  join agriculture.observation_template_version tv on tv.observation_template_version_id=b.observation_template_version_id
  where b.trial_id=p_trial_id and b.binding_role='PRIMARY' and b.required and b.effective_until is null and tv.version_status='ACTIVE';
  if primary_protocol_count=0 then raise exception 'TRIAL_REQUIRES_PRIMARY_OBSERVATION_PROTOCOL' using errcode='23514'; end if;

  update agriculture.trial
  set lifecycle_status='ACTIVE',
      governance_decision_id=p_governance_decision_id,
      updated_by=p_actor_id,
      updated_at=now(),
      start_date=coalesce(start_date,current_date)
  where trial_id=p_trial_id
  returning * into r;

  return r;
end $$;


ALTER FUNCTION "agriculture"."api_activate_trial"("p_trial_id" "uuid", "p_governance_decision_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_actor_has_capability"("p_actor_id" "uuid", "p_capability" "text", "p_country_code" character DEFAULT NULL::"bpchar") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE cap text:=lower(btrim(p_capability)); allowed boolean:=false;
BEGIN
 IF p_actor_id IS NULL OR NOT EXISTS(SELECT 1 FROM agriculture.actor WHERE actor_id=p_actor_id AND active) THEN RETURN false; END IF;
 IF cap='community_capture' THEN
   RETURN EXISTS(SELECT 1 FROM agriculture.actor_access_assignment aaa WHERE aaa.actor_id=p_actor_id AND aaa.active AND aaa.access_profile_code='AGRICULTURE_RUNTIME_COMMUNITY' AND aaa.authority_scope='AGRICULTURE' AND (aaa.country_code IS NULL OR p_country_code IS NULL OR aaa.country_code=p_country_code));
 END IF;
 SELECT COALESCE(bool_or(CASE cap WHEN 'read' THEN ap.can_read_canonical_data WHEN 'create_draft' THEN ap.can_create_drafts WHEN 'update_draft' THEN ap.can_update_drafts WHEN 'submit_review' THEN ap.can_submit_for_review WHEN 'review' THEN ap.can_review WHEN 'approve' THEN ap.can_approve WHEN 'retire' THEN ap.can_retire WHEN 'read_audit' THEN ap.can_read_audit WHEN 'integrity_check' THEN ap.can_run_integrity_checks WHEN 'run_migrations' THEN ap.can_run_migrations ELSE false END),false) INTO allowed FROM agriculture.actor_access_assignment aaa JOIN agriculture.access_profile ap ON ap.access_profile_code=aaa.access_profile_code WHERE aaa.actor_id=p_actor_id AND aaa.active AND ap.active AND aaa.authority_scope='AGRICULTURE' AND (aaa.country_code IS NULL OR p_country_code IS NULL OR aaa.country_code=p_country_code);
 IF allowed THEN RETURN true; END IF;
 SELECT COALESCE(bool_or(CASE cap WHEN 'review' THEN ar.can_review WHEN 'approve' THEN ar.can_approve WHEN 'administer' THEN ar.can_administer WHEN 'run_migrations' THEN ar.can_run_migrations ELSE false END),false) INTO allowed FROM agriculture.actor_authority aa JOIN agriculture.authority_role ar ON ar.role_code=aa.role_code WHERE aa.actor_id=p_actor_id AND aa.active AND ar.active AND aa.authority_scope='AGRICULTURE' AND (aa.country_code IS NULL OR p_country_code IS NULL OR aa.country_code=p_country_code);
 RETURN allowed;
END; $$;


ALTER FUNCTION "agriculture"."api_actor_has_capability"("p_actor_id" "uuid", "p_capability" "text", "p_country_code" character) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."country_resource_domain_relevance" (
    "country_resource_domain_relevance_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "country_resource_candidate_id" "uuid" NOT NULL,
    "domain_code" "text" NOT NULL,
    "relevance_status" "text" DEFAULT 'POSSIBLE'::"text" NOT NULL,
    "relevance_summary" "text" NOT NULL,
    "evidence_strength" "text" DEFAULT 'UNASSESSED'::"text" NOT NULL,
    CONSTRAINT "country_resource_domain_relevance_evidence_strength_check" CHECK (("evidence_strength" = ANY (ARRAY['UNASSESSED'::"text", 'LIMITED'::"text", 'MODERATE'::"text", 'STRONG'::"text", 'CONTRADICTED'::"text"]))),
    CONSTRAINT "country_resource_domain_relevance_relevance_status_check" CHECK (("relevance_status" = ANY (ARRAY['POSSIBLE'::"text", 'PLAUSIBLE'::"text", 'SUPPORTED'::"text", 'NOT_RELEVANT'::"text", 'BLOCKED'::"text"])))
);


ALTER TABLE "agriculture"."country_resource_domain_relevance" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_add_country_resource_domain_relevance"("p_country_resource_candidate_id" "uuid", "p_domain_code" "text", "p_relevance_status" "text", "p_relevance_summary" "text", "p_evidence_strength" "text", "p_actor_id" "uuid") RETURNS "agriculture"."country_resource_domain_relevance"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.country_resource_domain_relevance; cc char(2);
BEGIN
 SELECT country_code INTO cc FROM agriculture.country_resource_candidate WHERE country_resource_candidate_id=p_country_resource_candidate_id AND scientific_status<>'ARCHIVED'; IF NOT FOUND THEN RAISE EXCEPTION 'COUNTRY_RESOURCE_CANDIDATE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 PERFORM agriculture.api_require_capability(p_actor_id,'update_draft',cc);
 INSERT INTO agriculture.country_resource_domain_relevance(country_resource_candidate_id,domain_code,relevance_status,relevance_summary,evidence_strength) VALUES(p_country_resource_candidate_id,p_domain_code,p_relevance_status,btrim(p_relevance_summary),p_evidence_strength)
 ON CONFLICT(country_resource_candidate_id,domain_code) DO UPDATE SET relevance_status=excluded.relevance_status,relevance_summary=excluded.relevance_summary,evidence_strength=excluded.evidence_strength RETURNING * INTO r; RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_add_country_resource_domain_relevance"("p_country_resource_candidate_id" "uuid", "p_domain_code" "text", "p_relevance_status" "text", "p_relevance_summary" "text", "p_evidence_strength" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."evidence_packet_item" (
    "evidence_packet_item_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "evidence_packet_id" "uuid" NOT NULL,
    "item_order" integer DEFAULT 1 NOT NULL,
    "evidence_item_type" "text" NOT NULL,
    "linked_entity_type" "text",
    "linked_entity_id" "uuid",
    "source_object_id" "uuid",
    "evidence_role" "text" DEFAULT 'SUPPORTING'::"text" NOT NULL,
    "item_summary" "text",
    "inclusion_status" "text" DEFAULT 'INCLUDED'::"text" NOT NULL,
    "added_by" "uuid",
    "added_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "evidence_packet_item_evidence_item_type_check" CHECK (("evidence_item_type" = ANY (ARRAY['SOURCE_OBJECT'::"text", 'OBSERVATION'::"text", 'MEASUREMENT'::"text", 'PHOTO'::"text", 'DOCUMENT'::"text", 'LAB_RESULT'::"text", 'FIELD_NOTE'::"text", 'INSTRUMENT_READING'::"text", 'DECISION'::"text", 'REVIEW'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "evidence_packet_item_evidence_role_check" CHECK (("evidence_role" = ANY (ARRAY['PRIMARY'::"text", 'SUPPORTING'::"text", 'CONTEXTUAL'::"text", 'CONTRADICTORY'::"text", 'EXCLUDED'::"text"]))),
    CONSTRAINT "evidence_packet_item_inclusion_status_check" CHECK (("inclusion_status" = ANY (ARRAY['INCLUDED'::"text", 'PENDING_REVIEW'::"text", 'EXCLUDED'::"text", 'SUPERSEDED'::"text"]))),
    CONSTRAINT "evidence_packet_item_item_order_check" CHECK (("item_order" >= 1))
);


ALTER TABLE "agriculture"."evidence_packet_item" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_add_evidence_packet_item"("p_evidence_packet_id" "uuid", "p_evidence_item_type" "text", "p_evidence_role" "text" DEFAULT 'SUPPORTING'::"text", "p_linked_entity_type" "text" DEFAULT NULL::"text", "p_linked_entity_id" "uuid" DEFAULT NULL::"uuid", "p_source_object_id" "uuid" DEFAULT NULL::"uuid", "p_item_summary" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."evidence_packet_item"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.evidence_packet_item; next_order integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.evidence_packet WHERE evidence_packet_id=p_evidence_packet_id AND packet_status='DRAFT') THEN RAISE EXCEPTION 'EVIDENCE_PACKET_MUST_BE_DRAFT' USING ERRCODE='55000'; END IF;
 IF p_linked_entity_id IS NULL AND p_source_object_id IS NULL THEN RAISE EXCEPTION 'EVIDENCE_ITEM_REQUIRES_LINKED_ENTITY_OR_SOURCE_OBJECT' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(max(item_order),0)+1 INTO next_order FROM agriculture.evidence_packet_item WHERE evidence_packet_id=p_evidence_packet_id;
 INSERT INTO agriculture.evidence_packet_item(evidence_packet_id,item_order,evidence_item_type,linked_entity_type,linked_entity_id,source_object_id,evidence_role,item_summary,inclusion_status,added_by)
 VALUES(p_evidence_packet_id,next_order,p_evidence_item_type,p_linked_entity_type,p_linked_entity_id,p_source_object_id,p_evidence_role,p_item_summary,'INCLUDED',p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_add_evidence_packet_item"("p_evidence_packet_id" "uuid", "p_evidence_item_type" "text", "p_evidence_role" "text", "p_linked_entity_type" "text", "p_linked_entity_id" "uuid", "p_source_object_id" "uuid", "p_item_summary" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."formulation_version_ingredient_line" (
    "formulation_version_ingredient_line_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "formulation_version_id" "uuid" NOT NULL,
    "ingredient_id" "uuid" NOT NULL,
    "inclusion_rate_percent" numeric(8,4) NOT NULL,
    "sequence_order" integer NOT NULL,
    "ingredient_role" "text" NOT NULL,
    "line_notes" "text",
    "data_class" "text" DEFAULT 'TEST'::"text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formulation_version_ingredient_lin_inclusion_rate_percent_check" CHECK ((("inclusion_rate_percent" >= (0)::numeric) AND ("inclusion_rate_percent" <= (100)::numeric))),
    CONSTRAINT "formulation_version_ingredient_line_data_class_check" CHECK (("data_class" = ANY (ARRAY['REAL'::"text", 'TEST'::"text", 'SYSTEM_SEED'::"text", 'AI_GENERATED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "formulation_version_ingredient_line_sequence_order_check" CHECK (("sequence_order" >= 1))
);


ALTER TABLE "agriculture"."formulation_version_ingredient_line" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_add_formulation_ingredient"("p_formulation_version_id" "uuid", "p_ingredient_id" "uuid", "p_inclusion_rate_percent" numeric, "p_sequence_order" integer, "p_ingredient_role" "text", "p_line_notes" "text" DEFAULT NULL::"text", "p_data_class" "text" DEFAULT 'TEST'::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."formulation_version_ingredient_line"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.formulation_version_ingredient_line; s text; total numeric;
BEGIN
 SELECT lifecycle_status INTO s FROM agriculture.formulation_version WHERE formulation_version_id=p_formulation_version_id;
 IF s IS NULL THEN RAISE EXCEPTION 'FORMULATION_VERSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 IF s<>'DRAFT' THEN RAISE EXCEPTION 'FORMULATION_LINES_EDITABLE_ONLY_IN_DRAFT' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM agriculture.ingredient WHERE ingredient_id=p_ingredient_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'FORMULATION_REQUIRES_ACTIVE_INGREDIENT' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(sum(inclusion_rate_percent),0) INTO total FROM agriculture.formulation_version_ingredient_line WHERE formulation_version_id=p_formulation_version_id AND is_active;
 IF total+p_inclusion_rate_percent>100 THEN RAISE EXCEPTION 'FORMULATION_TOTAL_INCLUSION_EXCEEDS_100_PERCENT' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.formulation_version_ingredient_line(formulation_version_id,ingredient_id,inclusion_rate_percent,sequence_order,ingredient_role,line_notes,data_class,is_active,created_by)
 VALUES(p_formulation_version_id,p_ingredient_id,p_inclusion_rate_percent,p_sequence_order,p_ingredient_role,p_line_notes,p_data_class,true,p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_add_formulation_ingredient"("p_formulation_version_id" "uuid", "p_ingredient_id" "uuid", "p_inclusion_rate_percent" numeric, "p_sequence_order" integer, "p_ingredient_role" "text", "p_line_notes" "text", "p_data_class" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_add_formulation_ingredient_line"("p_formulation_version_id" "uuid", "p_ingredient_id" "uuid", "p_inclusion_rate_percent" numeric, "p_sequence_order" integer, "p_ingredient_role" "text", "p_line_notes" "text" DEFAULT NULL::"text", "p_data_class" "text" DEFAULT 'TEST'::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."formulation_version_ingredient_line"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.formulation_version_ingredient_line; BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.formulation_version WHERE formulation_version_id=p_formulation_version_id AND trial_readiness='NOT_READY') THEN RAISE EXCEPTION 'INGREDIENT_LINES_ONLY_ALLOWED_BEFORE_TRIAL_READINESS' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM agriculture.ingredient WHERE ingredient_id=p_ingredient_id AND lifecycle_status<>'ARCHIVED') THEN RAISE EXCEPTION 'ACTIVE_INGREDIENT_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.formulation_version_ingredient_line(formulation_version_id,ingredient_id,inclusion_rate_percent,sequence_order,ingredient_role,line_notes,data_class,is_active,created_by) VALUES(p_formulation_version_id,p_ingredient_id,p_inclusion_rate_percent,p_sequence_order,btrim(p_ingredient_role),p_line_notes,p_data_class,true,p_actor_id) RETURNING * INTO r; RETURN r; END; $$;


