    "ingredient_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ingredient_code" "text" NOT NULL,
    "ingredient_name" "text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "material_class" "text" NOT NULL,
    "preparation_class" "text",
    "data_class" "text" DEFAULT 'MIGRATED_UNREVIEWED'::"text" NOT NULL,
    "country_code" character(2),
    "current_version_no" integer DEFAULT 1 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "retired_at" timestamp with time zone,
    "country_workspace_id" "uuid",
    CONSTRAINT "ingredient_current_version_no_check" CHECK (("current_version_no" >= 1)),
    CONSTRAINT "ingredient_data_class_check" CHECK (("data_class" = ANY (ARRAY['RESEARCHED'::"text", 'MIGRATED_UNREVIEWED'::"text", 'SCIENTIST_APPROVED'::"text", 'EXPERIMENTAL_UNVERIFIED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "ingredient_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'ACTIVE'::"text", 'SUSPENDED'::"text", 'RETIRED'::"text", 'SUPERSEDED'::"text", 'QUARANTINED'::"text"]))),
    CONSTRAINT "ingredient_material_class_check" CHECK (("material_class" = ANY (ARRAY['PLANT_DERIVED'::"text", 'ANIMAL_DERIVED'::"text", 'MICROBIAL'::"text", 'FERMENTATION_DERIVED'::"text", 'MARINE_DERIVED'::"text", 'NATURALLY_OCCURRING_MINERAL'::"text", 'GEOLOGICAL_MATERIAL'::"text", 'NATURAL_WASTE_OR_BYPRODUCT'::"text", 'RECOVERED_MINERAL_MATERIAL'::"text", 'OTHER_NATURAL_OR_BIOLOGICAL'::"text", 'SYNTHETIC_AGROCHEMICAL'::"text", 'UNDECLARED_CHEMICAL_BLEND'::"text", 'UNVERIFIED_PROPRIETARY_CHEMISTRY'::"text", 'PROHIBITED_OR_RESTRICTED_MATERIAL'::"text", 'UNSAFE_OR_UNIDENTIFIED_MATERIAL'::"text"]))),
    CONSTRAINT "ingredient_preparation_class_check" CHECK (("preparation_class" = ANY (ARRAY['UNPROCESSED'::"text", 'PHYSICALLY_PROCESSED'::"text", 'DRIED'::"text", 'GROUND'::"text", 'FILTERED'::"text", 'FERMENTED'::"text", 'WATER_EXTRACTED'::"text", 'OTHER_LOW_TRANSFORMATION'::"text"])))
);


ALTER TABLE "agriculture"."ingredient" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_amend_ingredient"("p_ingredient_id" "uuid", "p_amendment_rationale" "text", "p_actor_id" "uuid", "p_ingredient_name" "text" DEFAULT NULL::"text", "p_material_class" "text" DEFAULT NULL::"text", "p_preparation_class" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_foliar_compatibility" "text" DEFAULT NULL::"text", "p_fertigation_compatibility" "text" DEFAULT NULL::"text", "p_risks_contraindications" "text" DEFAULT NULL::"text", "p_mitigation_lever" "text" DEFAULT NULL::"text", "p_handling_storage_notes" "text" DEFAULT NULL::"text") RETURNS "agriculture"."ingredient"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE
 r agriculture.ingredient;
 v_current agriculture.ingredient%ROWTYPE;
 v_next integer;
BEGIN
 SELECT * INTO v_current FROM agriculture.ingredient WHERE ingredient_id=p_ingredient_id FOR UPDATE;
 IF v_current.ingredient_id IS NULL THEN RAISE EXCEPTION 'INGREDIENT_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 PERFORM agriculture.api_require_capability(p_actor_id,'update_draft',v_current.country_code);
 IF v_current.lifecycle_status NOT IN ('DRAFT','UNDER_REVIEW') THEN RAISE EXCEPTION 'INGREDIENT_AMENDMENT_REQUIRES_DRAFT_OR_UNDER_REVIEW' USING ERRCODE='55000'; END IF;
 IF nullif(btrim(p_amendment_rationale),'') IS NULL THEN RAISE EXCEPTION 'INGREDIENT_AMENDMENT_REQUIRES_RATIONALE' USING ERRCODE='23514'; END IF;
 v_next:=v_current.current_version_no+1;
 INSERT INTO agriculture.ingredient_version(ingredient_id,version_no,category,foliar_compatibility,fertigation_compatibility,risks_contraindications,mitigation_lever,handling_storage_notes,amendment_rationale,review_status,created_by)
 VALUES(p_ingredient_id,v_next,p_category,p_foliar_compatibility,p_fertigation_compatibility,p_risks_contraindications,p_mitigation_lever,p_handling_storage_notes,btrim(p_amendment_rationale),'PENDING',p_actor_id);
 UPDATE agriculture.ingredient
 SET ingredient_name=COALESCE(NULLIF(btrim(p_ingredient_name),''),ingredient_name),
     material_class=COALESCE(NULLIF(btrim(p_material_class),''),material_class),
     preparation_class=CASE WHEN p_preparation_class IS NULL THEN preparation_class ELSE NULLIF(btrim(p_preparation_class),'') END,
     current_version_no=v_next,
     updated_at=now()
 WHERE ingredient_id=p_ingredient_id
 RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_amend_ingredient"("p_ingredient_id" "uuid", "p_amendment_rationale" "text", "p_actor_id" "uuid", "p_ingredient_name" "text", "p_material_class" "text", "p_preparation_class" "text", "p_category" "text", "p_foliar_compatibility" "text", "p_fertigation_compatibility" "text", "p_risks_contraindications" "text", "p_mitigation_lever" "text", "p_handling_storage_notes" "text") OWNER TO "postgres";


