    CONSTRAINT "approved_learning_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "approved_learning_learning_type_check" CHECK (("learning_type" = ANY (ARRAY['POSITIVE'::"text", 'NEGATIVE'::"text", 'NEUTRAL'::"text", 'CONTRADICTION'::"text", 'MECHANISM'::"text", 'SAFETY'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "approved_learning_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['ACTIVE'::"text", 'SUSPENDED'::"text", 'SUPERSEDED'::"text", 'RETIRED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "approved_learning_no_self_supersession" CHECK ((("supersedes_approved_learning_id" IS NULL) OR ("supersedes_approved_learning_id" <> "approved_learning_id")))
);


ALTER TABLE "agriculture"."approved_learning" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_approve_learning_candidate"("p_learning_candidate_id" "uuid", "p_approved_learning_code" "text", "p_learning_type" "text", "p_applicability_scope" "jsonb", "p_limitation_summary" "text", "p_governance_decision_id" "uuid", "p_actor_id" "uuid") RETURNS "agriculture"."approved_learning"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'agriculture', 'public'
    AS $$
declare lc agriculture.learning_candidate; r agriculture.approved_learning; ds text;
begin
  perform agriculture.api_require_capability(p_actor_id,'approve',null);
  if p_actor_id is null then raise exception 'LEARNING_APPROVAL_REQUIRES_ACTOR' using errcode='23514'; end if;
  select decision_status into ds from agriculture.governance_decision where decision_id=p_governance_decision_id;
  if ds<>'APPROVED' then raise exception 'LEARNING_APPROVAL_REQUIRES_APPROVED_GOVERNANCE_DECISION' using errcode='23514'; end if;
  select * into lc from agriculture.learning_candidate where learning_candidate_id=p_learning_candidate_id for update;
  if lc.learning_candidate_id is null or lc.candidate_status<>'UNDER_REVIEW' then raise exception 'LEARNING_CANDIDATE_NOT_UNDER_REVIEW' using errcode='55000'; end if;
  if exists(select 1 from agriculture.contradiction_record where subject_entity_type=lc.subject_entity_type and subject_entity_id=lc.subject_entity_id and lifecycle_status in ('OPEN','UNDER_REVIEW') and severity in ('HIGH','CRITICAL')) then raise exception 'HIGH_OR_CRITICAL_CONTRADICTION_BLOCKS_LEARNING_APPROVAL' using errcode='23514'; end if;
  update agriculture.learning_candidate set candidate_status='APPROVED',governance_decision_id=p_governance_decision_id,reviewed_by=p_actor_id,reviewed_at=now() where learning_candidate_id=lc.learning_candidate_id returning * into lc;
  insert into agriculture.approved_learning(approved_learning_code,learning_candidate_id,learning_type,learning_statement,applicability_scope,limitation_summary,evidence_packet_id,governance_decision_id,lifecycle_status,approved_by,approved_at,country_workspace_id)
  values(upper(btrim(p_approved_learning_code)),lc.learning_candidate_id,p_learning_type,lc.learning_statement,coalesce(p_applicability_scope,'{}'::jsonb),p_limitation_summary,lc.evidence_packet_id,p_governance_decision_id,'ACTIVE',p_actor_id,now(),lc.country_workspace_id) returning * into r;
  return r;
end $$;


ALTER FUNCTION "agriculture"."api_approve_learning_candidate"("p_learning_candidate_id" "uuid", "p_approved_learning_code" "text", "p_learning_type" "text", "p_applicability_scope" "jsonb", "p_limitation_summary" "text", "p_governance_decision_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_approve_learning_candidate"("p_learning_candidate_id" "uuid", "p_approved_learning_code" "text", "p_learning_type" "text", "p_applicability_scope" "jsonb", "p_governance_decision_id" "uuid", "p_actor_id" "uuid", "p_limitation_summary" "text" DEFAULT NULL::"text") RETURNS "agriculture"."approved_learning"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'agriculture', 'public'
    AS $$
begin
  return agriculture.api_approve_learning_candidate(p_learning_candidate_id,p_approved_learning_code,p_learning_type,p_applicability_scope,p_limitation_summary,p_governance_decision_id,p_actor_id);
end $$;


ALTER FUNCTION "agriculture"."api_approve_learning_candidate"("p_learning_candidate_id" "uuid", "p_approved_learning_code" "text", "p_learning_type" "text", "p_applicability_scope" "jsonb", "p_governance_decision_id" "uuid", "p_actor_id" "uuid", "p_limitation_summary" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."discovery_candidate" (
    "discovery_candidate_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "candidate_code" "text" NOT NULL,
    "candidate_name" "text" NOT NULL,
    "candidate_object_type" "text" NOT NULL,
    "discovery_signal_id" "uuid",
    "country_code" character(2),
    "material_class" "text",
    "source_material" "text",
    "preparation_class" "text",
    "hypothesised_pathway" "text",
    "candidate_summary" "text" NOT NULL,
    "uncertainty_summary" "text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'DISCOVERY_CANDIDATE'::"text" NOT NULL,
    "canonical_ingredient_id" "uuid",
    "governance_decision_id" "uuid",
    "evidence_packet_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "discovery_candidate_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "discovery_candidate_candidate_object_type_check" CHECK (("candidate_object_type" = ANY (ARRAY['INGREDIENT'::"text", 'MECHANISM'::"text", 'METHOD'::"text", 'FORMULATION_STRATEGY'::"text", 'PROCESS'::"text", 'BIOLOGICAL_RELATIONSHIP'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "discovery_candidate_canonical_link_consistency" CHECK ((("canonical_ingredient_id" IS NULL) OR (("lifecycle_status" = ANY (ARRAY['APPROVED_RESEARCH_INGREDIENT'::"text", 'PROVEN_CANONICAL'::"text"])) AND ("governance_decision_id" IS NOT NULL)))),
    CONSTRAINT "discovery_candidate_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DISCOVERY_CANDIDATE'::"text", 'IDENTITY_REVIEW'::"text", 'PRELIMINARY_EVIDENCE_REVIEW'::"text", 'MECHANISM_HYPOTHESIS'::"text", 'SAFETY_AND_ECOLOGICAL_REVIEW'::"text", 'LABORATORY_CANDIDATE'::"text", 'SCIENTIST_ADMIN_DECISION'::"text", 'UNDER_REVIEW'::"text", 'REVIEWED'::"text", 'INVESTIGATION_READY'::"text", 'APPROVED_RESEARCH_INGREDIENT'::"text", 'CONTROLLED_TRIAL'::"text", 'PROVEN_CANONICAL'::"text", 'REJECTED'::"text", 'SUSPENDED'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "agriculture"."discovery_candidate" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_discovery_candidate"("p_discovery_candidate_id" "uuid", "p_reason" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."discovery_candidate"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.discovery_candidate;
BEGIN
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ARCHIVE_REASON_REQUIRED' USING ERRCODE='23514'; END IF;
 UPDATE agriculture.discovery_candidate SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_reason),updated_by=p_actor_id,updated_at=now() WHERE discovery_candidate_id=p_discovery_candidate_id AND lifecycle_status<>'ARCHIVED' RETURNING * INTO r;
 IF r.discovery_candidate_id IS NULL THEN SELECT * INTO r FROM agriculture.discovery_candidate WHERE discovery_candidate_id=p_discovery_candidate_id; END IF;
 IF r.discovery_candidate_id IS NULL THEN RAISE EXCEPTION 'DISCOVERY_CANDIDATE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_archive_discovery_candidate"("p_discovery_candidate_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_foundation_record"("p_entity_type" "text", "p_entity_id" "uuid", "p_reason" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE n integer; t text:=upper(btrim(p_entity_type));
BEGIN
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ARCHIVE_REASON_REQUIRED' USING ERRCODE='23514'; END IF;
 CASE t
  WHEN 'ORGANIZATION' THEN UPDATE agriculture.organization SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=p_reason,updated_by=p_actor_id,updated_at=now() WHERE organization_id=p_entity_id AND lifecycle_status<>'ARCHIVED';
  WHEN 'FARM' THEN UPDATE agriculture.farm SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=p_reason,updated_by=p_actor_id,updated_at=now() WHERE farm_id=p_entity_id AND lifecycle_status<>'ARCHIVED';
  WHEN 'LOCATION' THEN UPDATE agriculture.location SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=p_reason,updated_by=p_actor_id,updated_at=now() WHERE location_id=p_entity_id AND lifecycle_status<>'ARCHIVED';
  WHEN 'CROP' THEN UPDATE agriculture.crop SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=p_reason,updated_by=p_actor_id,updated_at=now() WHERE crop_id=p_entity_id AND lifecycle_status<>'ARCHIVED';
  WHEN 'VARIETY' THEN UPDATE agriculture.variety SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=p_reason,updated_by=p_actor_id,updated_at=now() WHERE variety_id=p_entity_id AND lifecycle_status<>'ARCHIVED';
  WHEN 'AGRICULTURAL_PROBLEM' THEN UPDATE agriculture.agricultural_problem SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=p_reason,updated_by=p_actor_id,updated_at=now() WHERE agricultural_problem_id=p_entity_id AND lifecycle_status<>'ARCHIVED';
  ELSE RAISE EXCEPTION 'UNSUPPORTED_FOUNDATION_ENTITY_TYPE: %',t USING ERRCODE='22023';
 END CASE;
 GET DIAGNOSTICS n=ROW_COUNT;
 RETURN jsonb_build_object('ok',true,'entity_type',t,'entity_id',p_entity_id,'changed',n=1);
END; $$;


ALTER FUNCTION "agriculture"."api_archive_foundation_record"("p_entity_type" "text", "p_entity_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_ingredient"("p_ingredient_id" "uuid", "p_archive_reason" "text", "p_actor_id" "uuid") RETURNS "agriculture"."ingredient"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.ingredient; v_country char(2);
BEGIN
 SELECT country_code INTO v_country FROM agriculture.ingredient WHERE ingredient_id=p_ingredient_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'INGREDIENT_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 PERFORM agriculture.api_require_capability(p_actor_id,'retire',v_country);
 IF nullif(btrim(p_archive_reason),'') IS NULL THEN RAISE EXCEPTION 'INGREDIENT_ARCHIVE_REQUIRES_REASON' USING ERRCODE='23514'; END IF;
 IF EXISTS(
   SELECT 1 FROM agriculture.formulation_version_ingredient_line vil
   JOIN agriculture.formulation_version fv ON fv.formulation_version_id=vil.formulation_version_id
   WHERE vil.ingredient_id=p_ingredient_id AND vil.is_active AND fv.lifecycle_status='APPROVED' AND fv.trial_readiness='READY_FOR_TRIAL'
 ) THEN RAISE EXCEPTION 'INGREDIENT_IN_ACTIVE_READY_FORMULATION_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF;
 UPDATE agriculture.ingredient
 SET lifecycle_status='RETIRED',data_class='ARCHIVED',retired_at=now(),updated_at=now()
 WHERE ingredient_id=p_ingredient_id AND lifecycle_status NOT IN ('RETIRED','SUPERSEDED')
 RETURNING * INTO r;
 IF r.ingredient_id IS NULL THEN RAISE EXCEPTION 'INGREDIENT_NOT_ARCHIVABLE' USING ERRCODE='55000'; END IF;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_archive_ingredient"("p_ingredient_id" "uuid", "p_archive_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."observation" (
    "observation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "observation_code" "text" NOT NULL,
    "trial_id" "uuid" NOT NULL,
    "plot_id" "uuid" NOT NULL,
    "observation_template_version_id" "uuid",
    "observed_at" timestamp with time zone NOT NULL,
    "observer_id" "uuid",
    "observation_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "notes" "text",
    "input_submission_id" "uuid",
    "data_quality_assessment_id" "uuid",
    "evidence_packet_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "observation_archive_consistency" CHECK (((("observation_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("observation_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "observation_observation_status_check" CHECK (("observation_status" = ANY (ARRAY['DRAFT'::"text", 'SUBMITTED'::"text", 'VALIDATING'::"text", 'VALID'::"text", 'VALID_WITH_WARNINGS'::"text", 'QUARANTINED'::"text", 'REJECTED'::"text", 'REVIEWED'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "agriculture"."observation" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_observation"("p_observation_id" "uuid", "p_reason" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."observation"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.observation;
BEGIN
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ARCHIVE_REASON_REQUIRED' USING ERRCODE='23514'; END IF;
 UPDATE agriculture.observation SET observation_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_reason),updated_at=now() WHERE observation_id=p_observation_id AND observation_status<>'ARCHIVED' RETURNING * INTO r;
 IF r.observation_id IS NULL THEN SELECT * INTO r FROM agriculture.observation WHERE observation_id=p_observation_id; END IF;
 IF r.observation_id IS NULL THEN RAISE EXCEPTION 'OBSERVATION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_archive_observation"("p_observation_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."plot" (
    "plot_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "plot_code" "text" NOT NULL,
    "trial_id" "uuid" NOT NULL,
    "plot_name" "text" NOT NULL,
    "replicate_number" integer,
    "treatment_role" "text" DEFAULT 'TREATMENT'::"text" NOT NULL,
    "formulation_version_id" "uuid",
    "latitude" numeric(9,6),
    "longitude" numeric(9,6),
    "area_value" numeric,
    "area_unit" "text",
    "lifecycle_status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "plot_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "plot_area_value_check" CHECK ((("area_value" IS NULL) OR ("area_value" > (0)::numeric))),
    CONSTRAINT "plot_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "plot_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'ACTIVE'::"text", 'PAUSED'::"text", 'COMPLETED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "plot_longitude_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "plot_replicate_number_check" CHECK ((("replicate_number" IS NULL) OR ("replicate_number" >= 1))),
    CONSTRAINT "plot_treatment_role_check" CHECK (("treatment_role" = ANY (ARRAY['CONTROL'::"text", 'TREATMENT'::"text", 'REFERENCE'::"text", 'OTHER'::"text"])))
);


ALTER TABLE "agriculture"."plot" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_plot"("p_plot_id" "uuid", "p_reason" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."plot"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.plot; ts text; BEGIN IF p_actor_id IS NULL OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'PLOT_ARCHIVE_REQUIRES_ACTOR_AND_REASON' USING ERRCODE='23514'; END IF; SELECT t.lifecycle_status INTO ts FROM agriculture.plot p JOIN agriculture.trial t ON t.trial_id=p.trial_id WHERE p.plot_id=p_plot_id; IF ts='ACTIVE' THEN RAISE EXCEPTION 'PLOT_IN_ACTIVE_TRIAL_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF; UPDATE agriculture.plot SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_reason),updated_by=p_actor_id,updated_at=now() WHERE plot_id=p_plot_id AND lifecycle_status<>'ARCHIVED' RETURNING * INTO r; IF r.plot_id IS NULL THEN RAISE EXCEPTION 'PLOT_NOT_FOUND_OR_ALREADY_ARCHIVED' USING ERRCODE='55000'; END IF; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_archive_plot"("p_plot_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_reference_entity"("p_entity_type" "text", "p_entity_id" "uuid", "p_archive_reason" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE et text:=upper(btrim(p_entity_type)); affected integer:=0; BEGIN IF p_actor_id IS NULL OR nullif(btrim(p_archive_reason),'') IS NULL THEN RAISE EXCEPTION 'REFERENCE_ARCHIVE_REQUIRES_ACTOR_AND_REASON' USING ERRCODE='23514'; END IF; IF et='CROP' THEN IF EXISTS(SELECT 1 FROM agriculture.trial WHERE crop_id=p_entity_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'CROP_USED_BY_ACTIVE_TRIAL_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF; UPDATE agriculture.crop SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_archive_reason),updated_by=p_actor_id,updated_at=now() WHERE crop_id=p_entity_id AND lifecycle_status<>'ARCHIVED'; GET DIAGNOSTICS affected=ROW_COUNT; ELSIF et='VARIETY' THEN IF EXISTS(SELECT 1 FROM agriculture.trial WHERE variety_id=p_entity_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'VARIETY_USED_BY_ACTIVE_TRIAL_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF; UPDATE agriculture.variety SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_archive_reason),updated_by=p_actor_id,updated_at=now() WHERE variety_id=p_entity_id AND lifecycle_status<>'ARCHIVED'; GET DIAGNOSTICS affected=ROW_COUNT; ELSIF et='ORGANIZATION' THEN IF EXISTS(SELECT 1 FROM agriculture.trial WHERE organization_id=p_entity_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'ORGANIZATION_USED_BY_ACTIVE_TRIAL_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF; UPDATE agriculture.organization SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_archive_reason),updated_by=p_actor_id,updated_at=now() WHERE organization_id=p_entity_id AND lifecycle_status<>'ARCHIVED'; GET DIAGNOSTICS affected=ROW_COUNT; ELSIF et='FARM' THEN IF EXISTS(SELECT 1 FROM agriculture.trial WHERE farm_id=p_entity_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'FARM_USED_BY_ACTIVE_TRIAL_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF; UPDATE agriculture.farm SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_archive_reason),updated_by=p_actor_id,updated_at=now() WHERE farm_id=p_entity_id AND lifecycle_status<>'ARCHIVED'; GET DIAGNOSTICS affected=ROW_COUNT; ELSIF et='LOCATION' THEN IF EXISTS(SELECT 1 FROM agriculture.trial WHERE location_id=p_entity_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'LOCATION_USED_BY_ACTIVE_TRIAL_CANNOT_BE_ARCHIVED' USING ERRCODE='23514'; END IF; UPDATE agriculture.location SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_archive_reason),updated_by=p_actor_id,updated_at=now() WHERE location_id=p_entity_id AND lifecycle_status<>'ARCHIVED'; GET DIAGNOSTICS affected=ROW_COUNT; ELSE RAISE EXCEPTION 'UNSUPPORTED_REFERENCE_ENTITY_TYPE: %',et USING ERRCODE='22023'; END IF; IF affected=0 THEN RAISE EXCEPTION 'REFERENCE_ENTITY_NOT_FOUND_OR_ALREADY_ARCHIVED' USING ERRCODE='55000'; END IF; RETURN jsonb_build_object('entity_type',et,'entity_id',p_entity_id,'status','ARCHIVED','archive_reason',btrim(p_archive_reason)); END; $$;


ALTER FUNCTION "agriculture"."api_archive_reference_entity"("p_entity_type" "text", "p_entity_id" "uuid", "p_archive_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_archive_trial"("p_trial_id" "uuid", "p_reason" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."trial"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.trial; BEGIN IF p_actor_id IS NULL OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'TRIAL_ARCHIVE_REQUIRES_ACTOR_AND_REASON' USING ERRCODE='23514'; END IF; UPDATE agriculture.trial SET lifecycle_status='ARCHIVED',archived_by=p_actor_id,archived_at=now(),archive_reason=btrim(p_reason),updated_by=p_actor_id,updated_at=now() WHERE trial_id=p_trial_id AND lifecycle_status IN ('DRAFT','COMPLETED','CANCELLED') RETURNING * INTO r; IF r.trial_id IS NULL THEN RAISE EXCEPTION 'TRIAL_NOT_ARCHIVABLE_OR_NOT_FOUND' USING ERRCODE='55000'; END IF; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_archive_trial"("p_trial_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


