    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid" NOT NULL,
    "source_object_id" "uuid" NOT NULL,
    "provenance_type" "text" NOT NULL,
    "provenance_summary" "text" NOT NULL,
    "claim_scope" "text",
    "verified_status" "text" DEFAULT 'UNVERIFIED'::"text" NOT NULL,
    "verified_by" "uuid",
    "verified_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "provenance_assertion_provenance_type_check" CHECK (("provenance_type" = ANY (ARRAY['CREATED_FROM'::"text", 'DERIVED_FROM'::"text", 'SUPPORTED_BY'::"text", 'OBSERVED_IN'::"text", 'MEASURED_BY'::"text", 'REPORTED_BY'::"text", 'MIGRATED_FROM'::"text", 'REFERENCES'::"text", 'CONTRADICTED_BY'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "provenance_assertion_verified_status_check" CHECK (("verified_status" = ANY (ARRAY['UNVERIFIED'::"text", 'VERIFIED'::"text", 'PARTIALLY_VERIFIED'::"text", 'REJECTED'::"text"]))),
    CONSTRAINT "provenance_verification_consistency" CHECK (((("verified_status" = ANY (ARRAY['VERIFIED'::"text", 'PARTIALLY_VERIFIED'::"text", 'REJECTED'::"text"])) AND ("verified_by" IS NOT NULL) AND ("verified_at" IS NOT NULL)) OR ("verified_status" = 'UNVERIFIED'::"text")))
);


ALTER TABLE "agriculture"."provenance_assertion" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_assert_provenance"("p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_source_object_id" "uuid", "p_provenance_type" "text", "p_provenance_summary" "text", "p_claim_scope" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."provenance_assertion"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.provenance_assertion;
BEGIN
 IF nullif(btrim(p_provenance_summary),'') IS NULL THEN RAISE EXCEPTION 'PROVENANCE_SUMMARY_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.provenance_assertion(subject_entity_type,subject_entity_id,source_object_id,provenance_type,provenance_summary,claim_scope,verified_status,created_by)
 VALUES(upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_source_object_id,p_provenance_type,btrim(p_provenance_summary),p_claim_scope,'UNVERIFIED',p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_assert_provenance"("p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_source_object_id" "uuid", "p_provenance_type" "text", "p_provenance_summary" "text", "p_claim_scope" "text", "p_actor_id" "uuid") OWNER TO "postgres";


