    "data_quality_assessment_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid" NOT NULL,
    "input_submission_id" "uuid",
    "quality_status" "text" NOT NULL,
    "completeness_status" "text" NOT NULL,
    "context_quality" "text" NOT NULL,
    "method_quality" "text" NOT NULL,
    "evidence_quality" "text" NOT NULL,
    "photo_quality" "text" DEFAULT 'NOT_APPLICABLE'::"text" NOT NULL,
    "assessment_summary" "text" NOT NULL,
    "assessed_by" "uuid",
    "assessed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "review_required" boolean DEFAULT false NOT NULL,
    "governance_review_id" "uuid",
    CONSTRAINT "data_quality_assessment_completeness_status_check" CHECK (("completeness_status" = ANY (ARRAY['INCOMPLETE'::"text", 'COMPLETE_WITH_WARNINGS'::"text", 'COMPLETE'::"text"]))),
    CONSTRAINT "data_quality_assessment_context_quality_check" CHECK (("context_quality" = ANY (ARRAY['MISSING'::"text", 'LIMITED'::"text", 'ADEQUATE'::"text", 'STRONG'::"text"]))),
    CONSTRAINT "data_quality_assessment_evidence_quality_check" CHECK (("evidence_quality" = ANY (ARRAY['UNASSESSED'::"text", 'LIMITED'::"text", 'MODERATE'::"text", 'STRONG'::"text"]))),
    CONSTRAINT "data_quality_assessment_method_quality_check" CHECK (("method_quality" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'REFERENCE_GRADE'::"text"]))),
    CONSTRAINT "data_quality_assessment_photo_quality_check" CHECK (("photo_quality" = ANY (ARRAY['NOT_APPLICABLE'::"text", 'MISSING'::"text", 'UNUSABLE'::"text", 'LIMITED'::"text", 'ACCEPTABLE'::"text", 'STRONG'::"text"]))),
    CONSTRAINT "data_quality_assessment_quality_status_check" CHECK (("quality_status" = ANY (ARRAY['UNASSESSED'::"text", 'ACCEPTABLE'::"text", 'ACCEPTABLE_WITH_WARNINGS'::"text", 'REVIEW_REQUIRED'::"text", 'QUARANTINED'::"text", 'REJECTED'::"text"])))
);


ALTER TABLE "agriculture"."data_quality_assessment" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_assess_data_quality"("p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_quality_status" "text", "p_completeness_status" "text", "p_context_quality" "text", "p_method_quality" "text", "p_evidence_quality" "text", "p_photo_quality" "text", "p_assessment_summary" "text", "p_review_required" boolean DEFAULT false, "p_input_submission_id" "uuid" DEFAULT NULL::"uuid", "p_governance_review_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."data_quality_assessment"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.data_quality_assessment;
BEGIN
 INSERT INTO agriculture.data_quality_assessment(subject_entity_type,subject_entity_id,input_submission_id,quality_status,completeness_status,context_quality,method_quality,evidence_quality,photo_quality,assessment_summary,assessed_by,review_required,governance_review_id)
 VALUES(upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_input_submission_id,p_quality_status,p_completeness_status,p_context_quality,p_method_quality,p_evidence_quality,p_photo_quality,btrim(p_assessment_summary),p_actor_id,p_review_required,p_governance_review_id)
 ON CONFLICT(subject_entity_type,subject_entity_id) DO UPDATE SET input_submission_id=EXCLUDED.input_submission_id,quality_status=EXCLUDED.quality_status,completeness_status=EXCLUDED.completeness_status,context_quality=EXCLUDED.context_quality,method_quality=EXCLUDED.method_quality,evidence_quality=EXCLUDED.evidence_quality,photo_quality=EXCLUDED.photo_quality,assessment_summary=EXCLUDED.assessment_summary,assessed_by=EXCLUDED.assessed_by,assessed_at=now(),review_required=EXCLUDED.review_required,governance_review_id=EXCLUDED.governance_review_id
 RETURNING * INTO r;
 IF upper(btrim(p_subject_entity_type))='OBSERVATION' THEN UPDATE agriculture.observation SET data_quality_assessment_id=r.data_quality_assessment_id,updated_at=now() WHERE observation_id=p_subject_entity_id; END IF;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_assess_data_quality"("p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_quality_status" "text", "p_completeness_status" "text", "p_context_quality" "text", "p_method_quality" "text", "p_evidence_quality" "text", "p_photo_quality" "text", "p_assessment_summary" "text", "p_review_required" boolean, "p_input_submission_id" "uuid", "p_governance_review_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


