    "review_status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "consent_usage_status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "source_object_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "photo_evidence_camera_direction_degrees_check" CHECK ((("camera_direction_degrees" IS NULL) OR (("camera_direction_degrees" >= (0)::numeric) AND ("camera_direction_degrees" <= 359.999)))),
    CONSTRAINT "photo_evidence_consent_usage_status_check" CHECK (("consent_usage_status" = ANY (ARRAY['PENDING'::"text", 'APPROVED_FOR_RESEARCH'::"text", 'RESTRICTED'::"text", 'WITHDRAWN'::"text", 'NOT_APPLICABLE'::"text"]))),
    CONSTRAINT "photo_evidence_context_validation_status_check" CHECK (("context_validation_status" = ANY (ARRAY['NOT_VALIDATED'::"text", 'VALID'::"text", 'VALID_WITH_WARNINGS'::"text", 'CONTEXT_MISMATCH'::"text", 'QUARANTINED'::"text", 'REJECTED'::"text"]))),
    CONSTRAINT "photo_evidence_file_size_bytes_check" CHECK (("file_size_bytes" > 0)),
    CONSTRAINT "photo_evidence_height_pixels_check" CHECK ((("height_pixels" IS NULL) OR ("height_pixels" > 0))),
    CONSTRAINT "photo_evidence_image_quality_status_check" CHECK (("image_quality_status" = ANY (ARRAY['UNASSESSED'::"text", 'ACCEPTABLE'::"text", 'ACCEPTABLE_WITH_WARNINGS'::"text", 'UNUSABLE'::"text", 'QUARANTINED'::"text", 'REJECTED'::"text"]))),
    CONSTRAINT "photo_evidence_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "photo_evidence_longitude_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "photo_evidence_photo_type_check" CHECK (("photo_type" = ANY (ARRAY['OVERVIEW'::"text", 'CLOSEUP'::"text", 'SCALE_REFERENCE'::"text", 'CONTROL'::"text", 'TREATMENT'::"text", 'SYMPTOM'::"text", 'HARVEST'::"text", 'SOIL_SURFACE'::"text", 'WATER_CONDITION'::"text", 'EQUIPMENT'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "photo_evidence_review_status_check" CHECK (("review_status" = ANY (ARRAY['PENDING'::"text", 'UNDER_REVIEW'::"text", 'APPROVED'::"text", 'REJECTED'::"text", 'SUPERSEDED'::"text"]))),
    CONSTRAINT "photo_evidence_width_pixels_check" CHECK ((("width_pixels" IS NULL) OR ("width_pixels" > 0)))
);


ALTER TABLE "agriculture"."photo_evidence" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_assess_photo_evidence"("p_photo_evidence_id" "uuid", "p_image_quality_status" "text", "p_context_validation_status" "text", "p_review_status" "text", "p_consent_usage_status" "text", "p_actor_id" "uuid") RETURNS "agriculture"."photo_evidence"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.photo_evidence; iq text:=upper(btrim(p_image_quality_status)); cv text:=upper(btrim(p_context_validation_status)); rs text:=upper(btrim(p_review_status)); cu text:=upper(btrim(p_consent_usage_status));
BEGIN
 IF p_actor_id IS NULL THEN RAISE EXCEPTION 'PHOTO_ASSESSMENT_REQUIRES_ACTOR' USING ERRCODE='23514'; END IF;
 cv:=CASE cv WHEN 'VALIDATED' THEN 'VALID' WHEN 'VALIDATED_WITH_WARNINGS' THEN 'VALID_WITH_WARNINGS' ELSE cv END;
 cu:=CASE cu WHEN 'APPROVED' THEN 'APPROVED_FOR_RESEARCH' ELSE cu END;
 rs:=CASE rs WHEN 'APPROVED_WITH_WARNINGS' THEN 'APPROVED' ELSE rs END;
 IF iq NOT IN ('ACCEPTABLE','ACCEPTABLE_WITH_WARNINGS','UNUSABLE','QUARANTINED','REJECTED') OR cv NOT IN ('VALID','VALID_WITH_WARNINGS','CONTEXT_MISMATCH','QUARANTINED','REJECTED') OR rs NOT IN ('APPROVED','REJECTED','UNDER_REVIEW','PENDING') OR cu NOT IN ('APPROVED_FOR_RESEARCH','RESTRICTED','WITHDRAWN','NOT_APPLICABLE','PENDING') THEN RAISE EXCEPTION 'INVALID_PHOTO_ASSESSMENT_STATUS' USING ERRCODE='22023'; END IF;
 IF rs='APPROVED' AND (iq IN ('UNUSABLE','QUARANTINED','REJECTED') OR cv IN ('CONTEXT_MISMATCH','QUARANTINED','REJECTED') OR cu='WITHDRAWN') THEN RAISE EXCEPTION 'PHOTO_APPROVAL_INCONSISTENT_WITH_VALIDATION' USING ERRCODE='23514'; END IF;
 UPDATE agriculture.photo_evidence SET image_quality_status=iq,context_validation_status=cv,review_status=rs,consent_usage_status=cu WHERE photo_evidence_id=p_photo_evidence_id RETURNING * INTO r;
 IF r.photo_evidence_id IS NULL THEN RAISE EXCEPTION 'PHOTO_EVIDENCE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 UPDATE observation_core.evidence_link SET review_status=CASE WHEN rs='APPROVED' THEN CASE WHEN iq='ACCEPTABLE_WITH_WARNINGS' OR cv='VALID_WITH_WARNINGS' THEN 'APPROVED_WITH_WARNINGS' ELSE 'APPROVED' END ELSE rs END WHERE photo_evidence_id=p_photo_evidence_id;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_assess_photo_evidence"("p_photo_evidence_id" "uuid", "p_image_quality_status" "text", "p_context_validation_status" "text", "p_review_status" "text", "p_consent_usage_status" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."resource_safety_ecology_gate" (
    "resource_safety_ecology_gate_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "resource_discovery_run_id" "uuid" NOT NULL,
    "contamination_status" "text" NOT NULL,
    "toxicity_review_status" "text" DEFAULT 'UNASSESSED'::"text" NOT NULL,
    "ecological_review_status" "text" DEFAULT 'UNASSESSED'::"text" NOT NULL,
    "unknown_material_flag" boolean DEFAULT true NOT NULL,
    "traditional_knowledge_only_flag" boolean DEFAULT false NOT NULL,
    "supplier_claim_only_flag" boolean DEFAULT false NOT NULL,
    "gate_status" "text" NOT NULL,
    "gate_reason" "text" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "resource_gate_human_review_consistency" CHECK (((("gate_status" = 'PASS_FOR_INVESTIGATION'::"text") AND ("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)) OR ("gate_status" <> 'PASS_FOR_INVESTIGATION'::"text"))),
    CONSTRAINT "resource_safety_ecology_gate_ecological_review_status_check" CHECK (("ecological_review_status" = ANY (ARRAY['UNASSESSED'::"text", 'LOW_CONCERN'::"text", 'REVIEW_REQUIRED'::"text", 'HIGH_CONCERN'::"text", 'PROHIBITIVE'::"text"]))),
    CONSTRAINT "resource_safety_ecology_gate_gate_status_check" CHECK (("gate_status" = ANY (ARRAY['BLOCKED'::"text", 'REVIEW_REQUIRED'::"text", 'PASS_FOR_INVESTIGATION'::"text"]))),
    CONSTRAINT "resource_safety_ecology_gate_toxicity_review_status_check" CHECK (("toxicity_review_status" = ANY (ARRAY['UNASSESSED'::"text", 'LOW_CONCERN'::"text", 'REVIEW_REQUIRED'::"text", 'HIGH_CONCERN'::"text", 'PROHIBITIVE'::"text"])))
);


ALTER TABLE "agriculture"."resource_safety_ecology_gate" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_assess_resource_safety_gate"("p_resource_discovery_run_id" "uuid", "p_toxicity_review_status" "text" DEFAULT 'UNASSESSED'::"text", "p_ecological_review_status" "text" DEFAULT 'UNASSESSED'::"text", "p_traditional_knowledge_only" boolean DEFAULT false, "p_supplier_claim_only" boolean DEFAULT false, "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."resource_safety_ecology_gate"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE rrun agriculture.resource_discovery_run; c agriculture.country_resource_candidate; w agriculture.resource_waste_stream; g agriculture.resource_safety_ecology_gate; status text; reason text; unknown_flag boolean;
BEGIN
 SELECT * INTO rrun FROM agriculture.resource_discovery_run WHERE resource_discovery_run_id=p_resource_discovery_run_id;
 IF rrun.resource_discovery_run_id IS NULL THEN RAISE EXCEPTION 'RESOURCE_DISCOVERY_RUN_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 SELECT * INTO c FROM agriculture.country_resource_candidate WHERE country_resource_candidate_id=rrun.country_resource_candidate_id;
 IF rrun.resource_waste_stream_id IS NOT NULL THEN SELECT * INTO w FROM agriculture.resource_waste_stream WHERE resource_waste_stream_id=rrun.resource_waste_stream_id; END IF;
 unknown_flag:=c.composition_status<>'CHARACTERISED';
 IF COALESCE(w.contamination_status,'UNKNOWN')='PROHIBITIVE' OR p_toxicity_review_status='PROHIBITIVE' OR p_ecological_review_status='PROHIBITIVE' THEN status:='BLOCKED'; reason:='Prohibitive contamination, toxicity or ecological concern.';
 ELSIF COALESCE(w.contamination_status,'UNKNOWN') IN ('HIGH_CONCERN','REVIEW_REQUIRED','UNKNOWN') OR p_toxicity_review_status IN ('UNASSESSED','REVIEW_REQUIRED','HIGH_CONCERN') OR p_ecological_review_status IN ('UNASSESSED','REVIEW_REQUIRED','HIGH_CONCERN') OR unknown_flag OR p_traditional_knowledge_only OR p_supplier_claim_only THEN status:='REVIEW_REQUIRED'; reason:=concat_ws('; ',CASE WHEN unknown_flag THEN 'composition not fully characterised' END,CASE WHEN COALESCE(w.contamination_status,'UNKNOWN') IN ('HIGH_CONCERN','REVIEW_REQUIRED','UNKNOWN') THEN 'contamination requires review' END,CASE WHEN p_toxicity_review_status IN ('UNASSESSED','REVIEW_REQUIRED','HIGH_CONCERN') THEN 'toxicity review incomplete or concerning' END,CASE WHEN p_ecological_review_status IN ('UNASSESSED','REVIEW_REQUIRED','HIGH_CONCERN') THEN 'ecology review incomplete or concerning' END,CASE WHEN p_traditional_knowledge_only THEN 'traditional knowledge is not proof' END,CASE WHEN p_supplier_claim_only THEN 'supplier claim is not evidence' END);
 ELSE
   IF p_actor_id IS NULL OR NOT agriculture.api_actor_has_capability(p_actor_id,'review',c.country_code) THEN status:='REVIEW_REQUIRED'; reason:='Scientist/Admin review authority required before investigation pass.';
   ELSE status:='PASS_FOR_INVESTIGATION'; reason:='Safety/ecology gate passed for investigation only; not ingredient approval or efficacy proof.'; END IF;
 END IF;
 INSERT INTO agriculture.resource_safety_ecology_gate(resource_discovery_run_id,contamination_status,toxicity_review_status,ecological_review_status,unknown_material_flag,traditional_knowledge_only_flag,supplier_claim_only_flag,gate_status,gate_reason,reviewed_by,reviewed_at)
 VALUES(rrun.resource_discovery_run_id,COALESCE(w.contamination_status,'UNKNOWN'),p_toxicity_review_status,p_ecological_review_status,unknown_flag,p_traditional_knowledge_only,p_supplier_claim_only,status,reason,CASE WHEN status='PASS_FOR_INVESTIGATION' THEN p_actor_id ELSE NULL END,CASE WHEN status='PASS_FOR_INVESTIGATION' THEN now() ELSE NULL END) RETURNING * INTO g;
 RETURN g;
END; $$;


ALTER FUNCTION "agriculture"."api_assess_resource_safety_gate"("p_resource_discovery_run_id" "uuid", "p_toxicity_review_status" "text", "p_ecological_review_status" "text", "p_traditional_knowledge_only" boolean, "p_supplier_claim_only" boolean, "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."input_validation_run" (
    "input_validation_run_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "validation_run_code" "text" NOT NULL,
    "input_submission_id" "uuid" NOT NULL,
    "run_status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "validation_rule_set_version" "text",
    "initiated_by" "uuid",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "rules_evaluated" integer DEFAULT 0 NOT NULL,
    "pass_count" integer DEFAULT 0 NOT NULL,
    "warning_count" integer DEFAULT 0 NOT NULL,
    "fail_count" integer DEFAULT 0 NOT NULL,
    "quarantine_count" integer DEFAULT 0 NOT NULL,
    "result_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "input_validation_run_fail_count_check" CHECK (("fail_count" >= 0)),
    CONSTRAINT "input_validation_run_pass_count_check" CHECK (("pass_count" >= 0)),
    CONSTRAINT "input_validation_run_quarantine_count_check" CHECK (("quarantine_count" >= 0)),
    CONSTRAINT "input_validation_run_rules_evaluated_check" CHECK (("rules_evaluated" >= 0)),
    CONSTRAINT "input_validation_run_run_status_check" CHECK (("run_status" = ANY (ARRAY['PENDING'::"text", 'RUNNING'::"text", 'PASSED'::"text", 'PASSED_WITH_WARNINGS'::"text", 'QUARANTINED'::"text", 'FAILED'::"text", 'CANCELLED'::"text"]))),
    CONSTRAINT "input_validation_run_warning_count_check" CHECK (("warning_count" >= 0)),
    CONSTRAINT "validation_run_completion_consistency" CHECK (((("run_status" = ANY (ARRAY['PASSED'::"text", 'PASSED_WITH_WARNINGS'::"text", 'QUARANTINED'::"text", 'FAILED'::"text", 'CANCELLED'::"text"])) AND ("completed_at" IS NOT NULL)) OR ("run_status" = ANY (ARRAY['PENDING'::"text", 'RUNNING'::"text"])))),
    CONSTRAINT "validation_run_count_consistency" CHECK ((((("pass_count" + "warning_count") + "fail_count") + "quarantine_count") <= "rules_evaluated"))
);


ALTER TABLE "agriculture"."input_validation_run" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_begin_input_validation"("p_input_submission_id" "uuid", "p_rule_set_version" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."input_validation_run"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.input_validation_run;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.input_submission WHERE input_submission_id=p_input_submission_id) THEN RAISE EXCEPTION 'INPUT_SUBMISSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 INSERT INTO agriculture.input_validation_run(validation_run_code,input_submission_id,run_status,validation_rule_set_version,initiated_by,started_at)
 VALUES('VAL-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20)),p_input_submission_id,'RUNNING',p_rule_set_version,p_actor_id,now()) RETURNING * INTO r;
 UPDATE agriculture.input_submission SET submission_status='VALIDATING' WHERE input_submission_id=p_input_submission_id AND submission_status='RECEIVED';
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_begin_input_validation"("p_input_submission_id" "uuid", "p_rule_set_version" "text", "p_actor_id" "uuid") OWNER TO "postgres";


