    CONSTRAINT "reasoning_run_run_status_check" CHECK (("run_status" = ANY (ARRAY['PENDING'::"text", 'RUNNING'::"text", 'COMPLETED'::"text", 'COMPLETED_WITH_WARNINGS'::"text", 'FAILED'::"text", 'CANCELLED'::"text"]))),
