CREATE OR REPLACE FUNCTION "agriculture"."api_begin_reasoning_run"("p_reasoning_run_code" "text", "p_formulation_request_id" "uuid", "p_run_type" "text", "p_input_snapshot" "jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."reasoning_run"
