 INSERT INTO agriculture.reasoning_run(reasoning_run_code,formulation_request_id,run_type,run_status,input_snapshot,initiated_by,started_at) VALUES(upper(btrim(p_reasoning_run_code)),p_formulation_request_id,p_run_type,'RUNNING',COALESCE(p_input_snapshot,'{}'::jsonb),p_actor_id,now()) RETURNING * INTO r; RETURN r; END; $$;


