    "hypothesis_id" "uuid",
    "candidate_name" "text" NOT NULL,
    "candidate_summary" "text" NOT NULL,
    "candidate_status" "text" DEFAULT 'ADVISORY'::"text" NOT NULL,
    "evidence_packet_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "formulation_candidate_archive_consistency" CHECK (((("candidate_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("candidate_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "formulation_candidate_candidate_status_check" CHECK (("candidate_status" = ANY (ARRAY['ADVISORY'::"text", 'UNDER_REVIEW'::"text", 'ACCEPTED_FOR_VERSIONING'::"text", 'REJECTED'::"text", 'SUPERSEDED'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "agriculture"."formulation_candidate" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_formulation_candidate"("p_candidate_code" "text", "p_formulation_request_id" "uuid", "p_candidate_name" "text", "p_candidate_summary" "text", "p_reasoning_run_id" "uuid" DEFAULT NULL::"uuid", "p_hypothesis_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_packet_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."formulation_candidate"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.formulation_candidate; BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.formulation_request WHERE formulation_request_id=p_formulation_request_id AND lifecycle_status<>'ARCHIVED') THEN RAISE EXCEPTION 'ACTIVE_FORMULATION_REQUEST_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.formulation_candidate(candidate_code,formulation_request_id,reasoning_run_id,hypothesis_id,candidate_name,candidate_summary,candidate_status,evidence_packet_id,created_by) VALUES(upper(btrim(p_candidate_code)),p_formulation_request_id,p_reasoning_run_id,p_hypothesis_id,btrim(p_candidate_name),btrim(p_candidate_summary),'ADVISORY',p_evidence_packet_id,p_actor_id) RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_create_formulation_candidate"("p_candidate_code" "text", "p_formulation_request_id" "uuid", "p_candidate_name" "text", "p_candidate_summary" "text", "p_reasoning_run_id" "uuid", "p_hypothesis_id" "uuid", "p_evidence_packet_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


