    "formulation_request_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_code" "text" NOT NULL,
    "request_title" "text" NOT NULL,
    "problem_id" "uuid",
    "crop_id" "uuid",
    "variety_id" "uuid",
    "request_objective" "text" NOT NULL,
    "request_constraints" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "formulation_request_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "formulation_request_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'SUBMITTED'::"text", 'UNDER_REVIEW'::"text", 'COMPLETED'::"text", 'REJECTED'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "agriculture"."formulation_request" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_formulation_request"("p_request_code" "text", "p_request_title" "text", "p_request_objective" "text", "p_request_constraints" "jsonb" DEFAULT '{}'::"jsonb", "p_problem_id" "uuid" DEFAULT NULL::"uuid", "p_crop_id" "uuid" DEFAULT NULL::"uuid", "p_variety_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."formulation_request"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.formulation_request; BEGIN
 IF nullif(btrim(p_request_objective),'') IS NULL THEN RAISE EXCEPTION 'FORMULATION_REQUEST_OBJECTIVE_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.formulation_request(request_code,request_title,problem_id,crop_id,variety_id,request_objective,request_constraints,lifecycle_status,created_by,updated_by) VALUES(upper(btrim(p_request_code)),btrim(p_request_title),p_problem_id,p_crop_id,p_variety_id,btrim(p_request_objective),COALESCE(p_request_constraints,'{}'::jsonb),'DRAFT',p_actor_id,p_actor_id) RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_create_formulation_request"("p_request_code" "text", "p_request_title" "text", "p_request_objective" "text", "p_request_constraints" "jsonb", "p_problem_id" "uuid", "p_crop_id" "uuid", "p_variety_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."formulation_version" (
    "formulation_version_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "version_code" "text" NOT NULL,
    "formulation_name" "text" NOT NULL,
    "version_number" integer NOT NULL,
    "formulation_type" "text" DEFAULT 'OTHER'::"text" NOT NULL,
    "formulation_candidate_id" "uuid",
    "derived_from_version_id" "uuid",
    "change_type" "text" DEFAULT 'INITIAL'::"text" NOT NULL,
    "change_rationale" "text" NOT NULL,
    "expected_outcomes" "text",
    "data_class" "text" DEFAULT 'TEST'::"text" NOT NULL,
    "trial_readiness" "text" DEFAULT 'NOT_READY'::"text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "governance_decision_id" "uuid",
    "evidence_packet_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "country_workspace_id" "uuid",
    CONSTRAINT "formulation_version_approval_consistency" CHECK (((("lifecycle_status" = 'APPROVED'::"text") AND ("approved_by" IS NOT NULL) AND ("approved_at" IS NOT NULL) AND ("governance_decision_id" IS NOT NULL)) OR ("lifecycle_status" <> 'APPROVED'::"text"))),
    CONSTRAINT "formulation_version_change_type_check" CHECK (("change_type" = ANY (ARRAY['INITIAL'::"text", 'GO_HARD'::"text", 'GO_HARDER'::"text", 'CONTROL_VARIANT'::"text", 'DRY_GEL_VARIANT'::"text", 'WET_GEL_VARIANT'::"text", 'STRESS_RESPONSE_VARIANT'::"text", 'NUTRIENT_UPTAKE_VARIANT'::"text", 'COST_OPTIMISED_VARIANT'::"text", 'CORRECTION'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "formulation_version_data_class_check" CHECK (("data_class" = ANY (ARRAY['REAL'::"text", 'TEST'::"text", 'SYSTEM_SEED'::"text", 'AI_GENERATED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "formulation_version_formulation_type_check" CHECK (("formulation_type" = ANY (ARRAY['DRY_GEL'::"text", 'WET_GEL'::"text", 'CONTROL'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "formulation_version_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'APPROVED'::"text", 'REJECTED'::"text", 'SUPERSEDED'::"text", 'RETIRED'::"text"]))),
    CONSTRAINT "formulation_version_no_self_derivation" CHECK ((("derived_from_version_id" IS NULL) OR ("derived_from_version_id" <> "formulation_version_id"))),
    CONSTRAINT "formulation_version_trial_readiness_check" CHECK (("trial_readiness" = ANY (ARRAY['NOT_READY'::"text", 'SCIENTIST_REVIEW_REQUIRED'::"text", 'READY_FOR_TRIAL'::"text", 'BLOCKED'::"text", 'RETIRED'::"text"]))),
    CONSTRAINT "formulation_version_version_number_check" CHECK (("version_number" >= 1))
);


ALTER TABLE "agriculture"."formulation_version" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_formulation_version"("p_version_code" "text", "p_formulation_name" "text", "p_formulation_type" "text", "p_change_rationale" "text", "p_expected_outcomes" "text" DEFAULT NULL::"text", "p_data_class" "text" DEFAULT 'TEST'::"text", "p_derived_from_version_id" "uuid" DEFAULT NULL::"uuid", "p_change_type" "text" DEFAULT 'INITIAL'::"text", "p_candidate_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."formulation_version"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.formulation_version; next_no integer;
BEGIN
 IF nullif(btrim(p_change_rationale),'') IS NULL THEN RAISE EXCEPTION 'FORMULATION_CHANGE_RATIONALE_REQUIRED' USING ERRCODE='23514'; END IF;
 IF p_derived_from_version_id IS NOT NULL AND p_change_type='INITIAL' THEN RAISE EXCEPTION 'DERIVED_VERSION_REQUIRES_NON_INITIAL_CHANGE_TYPE' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(max(version_number),0)+1 INTO next_no FROM agriculture.formulation_version WHERE formulation_name=p_formulation_name;
 INSERT INTO agriculture.formulation_version(version_code,formulation_name,version_number,formulation_type,formulation_candidate_id,derived_from_version_id,change_type,change_rationale,expected_outcomes,data_class,trial_readiness,lifecycle_status,created_by)
 VALUES(p_version_code,p_formulation_name,next_no,p_formulation_type,p_candidate_id,p_derived_from_version_id,p_change_type,p_change_rationale,p_expected_outcomes,p_data_class,'NOT_READY','DRAFT',p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_formulation_version"("p_version_code" "text", "p_formulation_name" "text", "p_formulation_type" "text", "p_change_rationale" "text", "p_expected_outcomes" "text", "p_data_class" "text", "p_derived_from_version_id" "uuid", "p_change_type" "text", "p_candidate_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."governance_decision" (
    "decision_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "decision_code" "text" NOT NULL,
    "decision_type" "text" NOT NULL,
    "decision_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid" NOT NULL,
    "required_authority_role" "text",
    "rationale" "text" NOT NULL,
    "evidence_summary" "text",
    "outcome_summary" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "supersedes_decision_id" "uuid",
    CONSTRAINT "governance_decision_decision_status_check" CHECK (("decision_status" = ANY (ARRAY['DRAFT'::"text", 'PENDING_REVIEW'::"text", 'APPROVED'::"text", 'REJECTED'::"text", 'WITHDRAWN'::"text", 'SUPERSEDED'::"text"]))),
    CONSTRAINT "governance_decision_decision_type_check" CHECK (("decision_type" = ANY (ARRAY['CREATE'::"text", 'ACTIVATE'::"text", 'APPROVE'::"text", 'REJECT'::"text", 'AMEND'::"text", 'SUSPEND'::"text", 'RETIRE'::"text", 'SUPERSEDE'::"text", 'QUARANTINE'::"text", 'RELEASE_FROM_QUARANTINE'::"text", 'AUTHORISE_TRIAL'::"text", 'APPROVE_LEARNING'::"text", 'APPROVE_MEMORY'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "governance_decision_final_state_consistency" CHECK (((("decision_status" = ANY (ARRAY['APPROVED'::"text", 'REJECTED'::"text"])) AND ("decided_by" IS NOT NULL) AND ("decided_at" IS NOT NULL)) OR ("decision_status" <> ALL (ARRAY['APPROVED'::"text", 'REJECTED'::"text"])))),
    CONSTRAINT "governance_decision_no_self_supersession" CHECK ((("supersedes_decision_id" IS NULL) OR ("supersedes_decision_id" <> "decision_id")))
);


ALTER TABLE "agriculture"."governance_decision" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_governance_decision"("p_decision_code" "text", "p_decision_type" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_required_authority_role" "text", "p_rationale" "text", "p_evidence_summary" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."governance_decision"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.governance_decision;
BEGIN
 IF nullif(btrim(p_rationale),'') IS NULL THEN RAISE EXCEPTION 'GOVERNANCE_DECISION_RATIONALE_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.governance_decision(decision_code,decision_type,decision_status,subject_entity_type,subject_entity_id,required_authority_role,rationale,evidence_summary,created_by)
 VALUES(upper(btrim(p_decision_code)),p_decision_type,'DRAFT',upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_required_authority_role,btrim(p_rationale),p_evidence_summary,p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


