    CONSTRAINT "hypothesis_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'ACCEPTED_FOR_TEST'::"text", 'REJECTED'::"text", 'TESTED'::"text", 'SUPERSEDED'::"text", 'ARCHIVED'::"text"])))
);


