CREATE OR REPLACE FUNCTION "agriculture"."api_create_hypothesis"("p_hypothesis_code" "text", "p_hypothesis_statement" "text", "p_formulation_request_id" "uuid" DEFAULT NULL::"uuid", "p_reasoning_run_id" "uuid" DEFAULT NULL::"uuid", "p_expected_outcomes" "text" DEFAULT NULL::"text", "p_uncertainty_summary" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."hypothesis"
