 IF p_formulation_request_id IS NULL AND p_reasoning_run_id IS NULL THEN RAISE EXCEPTION 'HYPOTHESIS_REQUIRES_REQUEST_OR_REASONING_RUN' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.hypothesis(hypothesis_code,formulation_request_id,reasoning_run_id,hypothesis_statement,expected_outcomes,uncertainty_summary,lifecycle_status,created_by,updated_by) VALUES(upper(btrim(p_hypothesis_code)),p_formulation_request_id,p_reasoning_run_id,btrim(p_hypothesis_statement),p_expected_outcomes,p_uncertainty_summary,'DRAFT',p_actor_id,p_actor_id) RETURNING * INTO r; RETURN r; END; $$;


