CREATE OR REPLACE FUNCTION "agriculture"."api_create_ingredient"("p_ingredient_code" "text", "p_ingredient_name" "text", "p_material_class" "text", "p_preparation_class" "text" DEFAULT NULL::"text", "p_data_class" "text" DEFAULT 'EXPERIMENTAL_UNVERIFIED'::"text", "p_country_code" character DEFAULT NULL::"bpchar", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."ingredient"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.ingredient;
BEGIN
 IF nullif(btrim(p_ingredient_code),'') IS NULL OR nullif(btrim(p_ingredient_name),'') IS NULL THEN RAISE EXCEPTION 'INGREDIENT_CODE_AND_NAME_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.ingredient(ingredient_code,ingredient_name,lifecycle_status,material_class,preparation_class,data_class,country_code,created_by)
 VALUES(upper(btrim(p_ingredient_code)),btrim(p_ingredient_name),'DRAFT',p_material_class,p_preparation_class,p_data_class,p_country_code,p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_ingredient"("p_ingredient_code" "text", "p_ingredient_name" "text", "p_material_class" "text", "p_preparation_class" "text", "p_data_class" "text", "p_country_code" character, "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_ingredient"("p_ingredient_code" "text", "p_ingredient_name" "text", "p_material_class" "text", "p_creation_rationale" "text", "p_actor_id" "uuid", "p_preparation_class" "text" DEFAULT NULL::"text", "p_data_class" "text" DEFAULT 'EXPERIMENTAL_UNVERIFIED'::"text", "p_country_code" character DEFAULT NULL::"bpchar") RETURNS "agriculture"."ingredient"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.ingredient;
BEGIN
 PERFORM agriculture.api_require_capability(p_actor_id,'create_draft',p_country_code);
 IF nullif(btrim(p_creation_rationale),'') IS NULL THEN RAISE EXCEPTION 'INGREDIENT_CREATION_REQUIRES_RATIONALE' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.ingredient(ingredient_code,ingredient_name,lifecycle_status,material_class,preparation_class,data_class,country_code,current_version_no,created_by)
 VALUES(upper(btrim(p_ingredient_code)),btrim(p_ingredient_name),'DRAFT',p_material_class,p_preparation_class,p_data_class,p_country_code,1,p_actor_id)
 RETURNING * INTO r;
 INSERT INTO agriculture.ingredient_version(ingredient_id,version_no,amendment_rationale,review_status,created_by)
 VALUES(r.ingredient_id,1,btrim(p_creation_rationale),'PENDING',p_actor_id);
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_ingredient"("p_ingredient_code" "text", "p_ingredient_name" "text", "p_material_class" "text", "p_creation_rationale" "text", "p_actor_id" "uuid", "p_preparation_class" "text", "p_data_class" "text", "p_country_code" character) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_ingredient_version"("p_ingredient_id" "uuid", "p_amendment_rationale" "text", "p_actor_id" "uuid", "p_category" "text" DEFAULT NULL::"text", "p_foliar_compatibility" "text" DEFAULT NULL::"text", "p_fertigation_compatibility" "text" DEFAULT NULL::"text", "p_risks_contraindications" "text" DEFAULT NULL::"text", "p_mitigation_lever" "text" DEFAULT NULL::"text", "p_handling_storage_notes" "text" DEFAULT NULL::"text") RETURNS "agriculture"."ingredient_version"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.ingredient_version; next_no integer; v_country char(2); v_status text;
BEGIN
 SELECT country_code,lifecycle_status INTO v_country,v_status FROM agriculture.ingredient WHERE ingredient_id=p_ingredient_id FOR UPDATE;
 IF v_status IS NULL THEN RAISE EXCEPTION 'INGREDIENT_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 PERFORM agriculture.api_require_capability(p_actor_id,'update_draft',v_country);
 IF v_status NOT IN ('DRAFT','UNDER_REVIEW') THEN RAISE EXCEPTION 'INGREDIENT_VERSIONING_REQUIRES_DRAFT_OR_UNDER_REVIEW' USING ERRCODE='55000'; END IF;
 IF nullif(btrim(p_amendment_rationale),'') IS NULL THEN RAISE EXCEPTION 'INGREDIENT_VERSION_REQUIRES_RATIONALE' USING ERRCODE='23514'; END IF;
 SELECT current_version_no+1 INTO next_no FROM agriculture.ingredient WHERE ingredient_id=p_ingredient_id;
 INSERT INTO agriculture.ingredient_version(ingredient_id,version_no,category,foliar_compatibility,fertigation_compatibility,risks_contraindications,mitigation_lever,handling_storage_notes,amendment_rationale,review_status,created_by)
 VALUES(p_ingredient_id,next_no,p_category,p_foliar_compatibility,p_fertigation_compatibility,p_risks_contraindications,p_mitigation_lever,p_handling_storage_notes,btrim(p_amendment_rationale),'PENDING',p_actor_id)
 RETURNING * INTO r;
 UPDATE agriculture.ingredient SET current_version_no=next_no,updated_at=now() WHERE ingredient_id=p_ingredient_id;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_ingredient_version"("p_ingredient_id" "uuid", "p_amendment_rationale" "text", "p_actor_id" "uuid", "p_category" "text", "p_foliar_compatibility" "text", "p_fertigation_compatibility" "text", "p_risks_contraindications" "text", "p_mitigation_lever" "text", "p_handling_storage_notes" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."knowledge_gap" (
    "knowledge_gap_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "gap_code" "text" NOT NULL,
    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid" NOT NULL,
    "gap_type" "text" NOT NULL,
    "gap_statement" "text" NOT NULL,
    "why_it_matters" "text" NOT NULL,
    "proposed_resolution" "text",
    "priority_status" "text" DEFAULT 'UNASSESSED'::"text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'OPEN'::"text" NOT NULL,
    "evidence_packet_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolution_summary" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "knowledge_gap_gap_type_check" CHECK (("gap_type" = ANY (ARRAY['MISSING_EVIDENCE'::"text", 'INSUFFICIENT_REPLICATION'::"text", 'UNKNOWN_MECHANISM'::"text", 'CONTEXT_GAP'::"text", 'MEASUREMENT_GAP'::"text", 'SAFETY_GAP'::"text", 'ECOLOGICAL_GAP'::"text", 'CONTRADICTORY_EVIDENCE'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "knowledge_gap_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['OPEN'::"text", 'UNDER_INVESTIGATION'::"text", 'RESOLVED'::"text", 'ACCEPTED_UNCERTAINTY'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "knowledge_gap_priority_status_check" CHECK (("priority_status" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'CRITICAL'::"text"]))),
    CONSTRAINT "knowledge_gap_resolution_consistency" CHECK (((("lifecycle_status" = ANY (ARRAY['RESOLVED'::"text", 'ACCEPTED_UNCERTAINTY'::"text"])) AND ("resolved_by" IS NOT NULL) AND ("resolved_at" IS NOT NULL) AND ("resolution_summary" IS NOT NULL)) OR ("lifecycle_status" = ANY (ARRAY['OPEN'::"text", 'UNDER_INVESTIGATION'::"text", 'ARCHIVED'::"text"]))))
);


ALTER TABLE "agriculture"."knowledge_gap" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_knowledge_gap"("p_gap_code" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_gap_type" "text", "p_gap_statement" "text", "p_why_it_matters" "text", "p_proposed_resolution" "text" DEFAULT NULL::"text", "p_priority_status" "text" DEFAULT 'UNASSESSED'::"text", "p_evidence_packet_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."knowledge_gap"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.knowledge_gap; BEGIN
 INSERT INTO agriculture.knowledge_gap(gap_code,subject_entity_type,subject_entity_id,gap_type,gap_statement,why_it_matters,proposed_resolution,priority_status,evidence_packet_id,created_by)
 VALUES(upper(btrim(p_gap_code)),upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_gap_type,btrim(p_gap_statement),btrim(p_why_it_matters),p_proposed_resolution,p_priority_status,p_evidence_packet_id,p_actor_id) RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_create_knowledge_gap"("p_gap_code" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_gap_type" "text", "p_gap_statement" "text", "p_why_it_matters" "text", "p_proposed_resolution" "text", "p_priority_status" "text", "p_evidence_packet_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."learning_candidate" (
    "learning_candidate_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "learning_candidate_code" "text" NOT NULL,
    "candidate_type" "text" NOT NULL,
    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid" NOT NULL,
    "brain_evidence_eligibility_id" "uuid" NOT NULL,
    "evidence_packet_id" "uuid" NOT NULL,
    "learning_statement" "text" NOT NULL,
    "uncertainty_summary" "text",
    "contradiction_summary" "text",
    "candidate_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "governance_decision_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "learning_candidate_approval_consistency" CHECK (((("candidate_status" = 'APPROVED'::"text") AND ("governance_decision_id" IS NOT NULL) AND ("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)) OR ("candidate_status" <> 'APPROVED'::"text"))),
    CONSTRAINT "learning_candidate_archive_consistency" CHECK (((("candidate_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("candidate_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "learning_candidate_candidate_status_check" CHECK (("candidate_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'APPROVED'::"text", 'REJECTED'::"text", 'SUPERSEDED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "learning_candidate_candidate_type_check" CHECK (("candidate_type" = ANY (ARRAY['POSITIVE'::"text", 'NEGATIVE'::"text", 'NEUTRAL'::"text", 'CONTRADICTION'::"text", 'MECHANISM'::"text", 'SAFETY'::"text", 'OTHER'::"text"])))
);


ALTER TABLE "agriculture"."learning_candidate" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_learning_candidate"("p_learning_candidate_code" "text", "p_candidate_type" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_learning_statement" "text", "p_brain_evidence_eligibility_id" "uuid", "p_evidence_packet_id" "uuid", "p_uncertainty_summary" "text" DEFAULT NULL::"text", "p_contradiction_summary" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."learning_candidate"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.learning_candidate; es text; sid uuid; st text;
BEGIN
 SELECT eligibility_status,subject_entity_id,subject_entity_type INTO es,sid,st FROM agriculture.brain_evidence_eligibility WHERE brain_evidence_eligibility_id=p_brain_evidence_eligibility_id;
 IF es NOT IN ('ELIGIBLE','ELIGIBLE_WITH_WARNINGS') OR sid IS DISTINCT FROM p_subject_entity_id OR st IS DISTINCT FROM upper(btrim(p_subject_entity_type)) THEN RAISE EXCEPTION 'LEARNING_CANDIDATE_REQUIRES_MATCHING_ELIGIBLE_EVIDENCE' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.learning_candidate(learning_candidate_code,candidate_type,subject_entity_type,subject_entity_id,brain_evidence_eligibility_id,evidence_packet_id,learning_statement,uncertainty_summary,contradiction_summary,candidate_status,created_by)
 VALUES(upper(btrim(p_learning_candidate_code)),p_candidate_type,upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_brain_evidence_eligibility_id,p_evidence_packet_id,btrim(p_learning_statement),p_uncertainty_summary,p_contradiction_summary,'DRAFT',p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_learning_candidate"("p_learning_candidate_code" "text", "p_candidate_type" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_learning_statement" "text", "p_brain_evidence_eligibility_id" "uuid", "p_evidence_packet_id" "uuid", "p_uncertainty_summary" "text", "p_contradiction_summary" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_learning_candidate"("p_candidate_code" "text", "p_candidate_type" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_brain_evidence_eligibility_id" "uuid", "p_evidence_packet_id" "uuid", "p_learning_statement" "text", "p_uncertainty_summary" "text", "p_contradiction_summary" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."learning_candidate"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'agriculture', 'public'
    AS $$
declare r agriculture.learning_candidate; es text; cw uuid;
begin
  perform agriculture.api_require_capability(p_actor_id,'create_draft',null);
  select eligibility_status into es from agriculture.brain_evidence_eligibility where brain_evidence_eligibility_id=p_brain_evidence_eligibility_id and subject_entity_type=upper(btrim(p_subject_entity_type)) and subject_entity_id=p_subject_entity_id;
  if es not in ('ELIGIBLE','ELIGIBLE_WITH_WARNINGS') then raise exception 'LEARNING_REQUIRES_ELIGIBLE_BRAIN_EVIDENCE' using errcode='23514'; end if;
  if not exists(select 1 from agriculture.evidence_packet where evidence_packet_id=p_evidence_packet_id and packet_status in ('COMPLETE','APPROVED') and completeness_status='COMPLETE') then raise exception 'LEARNING_REQUIRES_COMPLETE_EVIDENCE_PACKET' using errcode='23514'; end if;
  if upper(btrim(p_subject_entity_type))='OUTCOME' then select country_workspace_id into cw from agriculture.outcome where outcome_id=p_subject_entity_id;
  elsif upper(btrim(p_subject_entity_type))='TRIAL' then select country_workspace_id into cw from agriculture.trial where trial_id=p_subject_entity_id;
  elsif upper(btrim(p_subject_entity_type))='OBSERVATION' then select country_workspace_id into cw from agriculture.observation where observation_id=p_subject_entity_id;
  end if;
  insert into agriculture.learning_candidate(learning_candidate_code,candidate_type,subject_entity_type,subject_entity_id,brain_evidence_eligibility_id,evidence_packet_id,learning_statement,uncertainty_summary,contradiction_summary,candidate_status,created_by,country_workspace_id)
  values(upper(btrim(p_candidate_code)),p_candidate_type,upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_brain_evidence_eligibility_id,p_evidence_packet_id,btrim(p_learning_statement),nullif(btrim(p_uncertainty_summary),''),nullif(btrim(p_contradiction_summary),''),'DRAFT',p_actor_id,cw) returning * into r;
  return r;
end $$;


ALTER FUNCTION "agriculture"."api_create_learning_candidate"("p_candidate_code" "text", "p_candidate_type" "text", "p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_brain_evidence_eligibility_id" "uuid", "p_evidence_packet_id" "uuid", "p_learning_statement" "text", "p_uncertainty_summary" "text", "p_contradiction_summary" "text", "p_actor_id" "uuid") OWNER TO "postgres";


