    "opportunity_profile_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "opportunity_profile_code" "text" NOT NULL,
    "discovery_candidate_id" "uuid" NOT NULL,
    "primary_opportunity" "text" NOT NULL,
    "additional_opportunities" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "scientific_novelty" "text" NOT NULL,
    "evidence_strength" "text" NOT NULL,
    "potential_upside" "text" NOT NULL,
    "research_difficulty" "text" NOT NULL,
    "main_uncertainties" "text" NOT NULL,
    "recommended_investigation" "text",
    "scientist_admin_review_required" boolean DEFAULT true NOT NULL,
    "profile_status" "text" DEFAULT 'ADVISORY'::"text" NOT NULL,
    "evidence_packet_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    CONSTRAINT "opportunity_profile_archive_consistency" CHECK (((("profile_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("profile_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "opportunity_profile_evidence_strength_check" CHECK (("evidence_strength" = ANY (ARRAY['UNASSESSED'::"text", 'LIMITED'::"text", 'MODERATE'::"text", 'STRONG'::"text", 'CONTRADICTED'::"text"]))),
    CONSTRAINT "opportunity_profile_potential_upside_check" CHECK (("potential_upside" = ANY (ARRAY['UNASSESSED'::"text", 'LIMITED'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'EXCEPTIONAL'::"text"]))),
    CONSTRAINT "opportunity_profile_profile_status_check" CHECK (("profile_status" = ANY (ARRAY['ADVISORY'::"text", 'UNDER_REVIEW'::"text", 'REVIEWED'::"text", 'SUPERSEDED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "opportunity_profile_research_difficulty_check" CHECK (("research_difficulty" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'VERY_HIGH'::"text"]))),
    CONSTRAINT "opportunity_profile_scientific_novelty_check" CHECK (("scientific_novelty" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'EXCEPTIONAL'::"text"])))
);


ALTER TABLE "agriculture"."opportunity_profile" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_opportunity_profile"("p_profile_code" "text", "p_discovery_candidate_id" "uuid", "p_primary_opportunity" "text", "p_scientific_novelty" "text", "p_evidence_strength" "text", "p_potential_upside" "text", "p_research_difficulty" "text", "p_main_uncertainties" "text", "p_additional_opportunities" "jsonb" DEFAULT '[]'::"jsonb", "p_recommended_investigation" "text" DEFAULT NULL::"text", "p_evidence_packet_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."opportunity_profile"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.opportunity_profile;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.discovery_candidate WHERE discovery_candidate_id=p_discovery_candidate_id AND lifecycle_status NOT IN ('REJECTED','SUSPENDED','ARCHIVED')) THEN RAISE EXCEPTION 'ACTIVE_DISCOVERY_CANDIDATE_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.opportunity_profile(opportunity_profile_code,discovery_candidate_id,primary_opportunity,additional_opportunities,scientific_novelty,evidence_strength,potential_upside,research_difficulty,main_uncertainties,recommended_investigation,scientist_admin_review_required,profile_status,evidence_packet_id,created_by)
 VALUES(upper(btrim(p_profile_code)),p_discovery_candidate_id,btrim(p_primary_opportunity),COALESCE(p_additional_opportunities,'[]'::jsonb),p_scientific_novelty,p_evidence_strength,p_potential_upside,p_research_difficulty,btrim(p_main_uncertainties),p_recommended_investigation,true,'ADVISORY',p_evidence_packet_id,p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


