CREATE OR REPLACE FUNCTION "agriculture"."api_create_plot"("p_trial_id" "uuid", "p_plot_code" "text", "p_plot_name" "text", "p_treatment_role" "text" DEFAULT 'TREATMENT'::"text", "p_formulation_version_id" "uuid" DEFAULT NULL::"uuid", "p_replicate_number" integer DEFAULT NULL::integer, "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_area_value" numeric DEFAULT NULL::numeric, "p_area_unit" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."plot"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.plot; ts text;
BEGIN
 SELECT lifecycle_status INTO ts FROM agriculture.trial WHERE trial_id=p_trial_id;
 IF ts IS NULL THEN RAISE EXCEPTION 'TRIAL_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 IF ts IN ('COMPLETED','CANCELLED','ARCHIVED') THEN RAISE EXCEPTION 'PLOT_CANNOT_BE_ADDED_TO_CLOSED_TRIAL' USING ERRCODE='55000'; END IF;
 INSERT INTO agriculture.plot(plot_code,trial_id,plot_name,replicate_number,treatment_role,formulation_version_id,latitude,longitude,area_value,area_unit,lifecycle_status,created_by)
 VALUES(upper(btrim(p_plot_code)),p_trial_id,btrim(p_plot_name),p_replicate_number,p_treatment_role,p_formulation_version_id,p_latitude,p_longitude,p_area_value,p_area_unit,'ACTIVE',p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_plot"("p_trial_id" "uuid", "p_plot_code" "text", "p_plot_name" "text", "p_treatment_role" "text", "p_formulation_version_id" "uuid", "p_replicate_number" integer, "p_latitude" numeric, "p_longitude" numeric, "p_area_value" numeric, "p_area_unit" "text", "p_actor_id" "uuid") OWNER TO "postgres";


