    CONSTRAINT "resource_recovery_pathway_pathway_type_check" CHECK (("pathway_type" = ANY (ARRAY['DIRECT_REUSE'::"text", 'COMPOSTING'::"text", 'FERMENTATION'::"text", 'EXTRACTION'::"text", 'MINERAL_RECOVERY'::"text", 'BIOLOGICAL_PROCESSING'::"text", 'PHYSICAL_PROCESSING'::"text", 'WATER_TREATMENT_MEDIA'::"text", 'SOIL_AMENDMENT_PROCESSING'::"text", 'FORMULATION_FEEDSTOCK'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "resource_recovery_pathway_recovery_feasibility_check" CHECK (("recovery_feasibility" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'VERY_HIGH'::"text"])))
);


ALTER TABLE "agriculture"."resource_recovery_pathway" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_create_resource_recovery_pathway"("p_resource_waste_stream_id" "uuid", "p_pathway_code" "text", "p_pathway_type" "text", "p_pathway_summary" "text", "p_recovery_feasibility" "text", "p_actor_id" "uuid", "p_processing_requirements" "text" DEFAULT NULL::"text") RETURNS "agriculture"."resource_recovery_pathway"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.resource_recovery_pathway; cc char(2);
BEGIN
 SELECT country_code INTO cc FROM agriculture.resource_waste_stream WHERE resource_waste_stream_id=p_resource_waste_stream_id AND recovery_status<>'ARCHIVED'; IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_WASTE_STREAM_NOT_FOUND' USING ERRCODE='P0002'; END IF; PERFORM agriculture.api_require_capability(p_actor_id,'create_draft',cc);
 INSERT INTO agriculture.resource_recovery_pathway(resource_waste_stream_id,pathway_code,pathway_type,pathway_summary,processing_requirements,recovery_feasibility,safety_review_required,ecology_review_required,lifecycle_status,created_by)
 VALUES(p_resource_waste_stream_id,upper(btrim(p_pathway_code)),p_pathway_type,btrim(p_pathway_summary),p_processing_requirements,p_recovery_feasibility,true,true,'ADVISORY',p_actor_id) RETURNING * INTO r; RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_create_resource_recovery_pathway"("p_resource_waste_stream_id" "uuid", "p_pathway_code" "text", "p_pathway_type" "text", "p_pathway_summary" "text", "p_recovery_feasibility" "text", "p_actor_id" "uuid", "p_processing_requirements" "text") OWNER TO "postgres";


