    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "operation_failure_event_failure_category_check" CHECK (("failure_category" = ANY (ARRAY['VALIDATION'::"text", 'AUTHENTICATION'::"text", 'AUTHORISATION'::"text", 'DATABASE'::"text", 'INTEGRITY'::"text", 'NETWORK'::"text", 'CONFIGURATION'::"text", 'DEPENDENCY'::"text", 'UNEXPECTED'::"text"]))),
    CONSTRAINT "operation_failure_event_severity_check" CHECK (("severity" = ANY (ARRAY['INFO'::"text", 'WARNING'::"text", 'ERROR'::"text", 'CRITICAL'::"text"])))
);


ALTER TABLE "agriculture"."operation_failure_event" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_record_operation_failure"("p_failure_code" "text", "p_failure_category" "text", "p_severity" "text", "p_safe_message" "text", "p_operation_run_id" "uuid" DEFAULT NULL::"uuid", "p_request_context_id" "uuid" DEFAULT NULL::"uuid", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_retryable" boolean DEFAULT false, "p_failure_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "agriculture"."operation_failure_event"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.operation_failure_event;
BEGIN
 INSERT INTO agriculture.operation_failure_event(operation_run_id,request_context_id,failure_code,failure_category,severity,safe_message,entity_type,entity_id,retryable,failure_context)
 VALUES(p_operation_run_id,p_request_context_id,upper(btrim(p_failure_code)),p_failure_category,p_severity,btrim(p_safe_message),p_entity_type,p_entity_id,p_retryable,COALESCE(p_failure_context,'{}'::jsonb)) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_record_operation_failure"("p_failure_code" "text", "p_failure_category" "text", "p_severity" "text", "p_safe_message" "text", "p_operation_run_id" "uuid", "p_request_context_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_retryable" boolean, "p_failure_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_record_outcome"("p_outcome_code" "text", "p_trial_id" "uuid", "p_outcome_type" "text", "p_outcome_summary" "text", "p_plot_id" "uuid" DEFAULT NULL::"uuid", "p_outcome_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_evidence_packet_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."outcome"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'agriculture', 'country_core', 'public'
    AS $$
declare r agriculture.outcome; cw uuid; has_country boolean;
begin
  perform agriculture.api_require_capability(p_actor_id,'create_draft',null);
  if nullif(btrim(p_outcome_summary),'') is null then raise exception 'OUTCOME_SUMMARY_REQUIRED' using errcode='23514'; end if;
  select country_workspace_id into cw from agriculture.trial where trial_id=p_trial_id and lifecycle_status in ('ACTIVE','COMPLETED');
  if not found then raise exception 'ACTIVE_TRIAL_NOT_FOUND' using errcode='P0002'; end if;
  select exists(select 1 from country_core.workspace_membership where actor_id=p_actor_id and membership_status='ACTIVE') into has_country;
  if cw is not null and not exists(select 1 from country_core.workspace_membership where actor_id=p_actor_id and country_workspace_id=cw and membership_status='ACTIVE') then raise exception 'TRIAL_COUNTRY_ACCESS_DENIED' using errcode='42501'; end if;
  if p_plot_id is not null and not exists(select 1 from agriculture.plot where plot_id=p_plot_id and trial_id=p_trial_id and lifecycle_status<>'ARCHIVED') then raise exception 'OUTCOME_PLOT_DOES_NOT_BELONG_TO_TRIAL' using errcode='23514'; end if;
  if not exists(select 1 from agriculture.observation where trial_id=p_trial_id and (p_plot_id is null or plot_id=p_plot_id) and observation_status='REVIEWED') then raise exception 'OUTCOME_REQUIRES_AT_LEAST_ONE_REVIEWED_OBSERVATION' using errcode='23514'; end if;
  insert into agriculture.outcome(outcome_code,trial_id,plot_id,outcome_type,outcome_status,outcome_summary,outcome_payload,evidence_packet_id,created_by,country_workspace_id)
  values(upper(btrim(p_outcome_code)),p_trial_id,p_plot_id,p_outcome_type,'DRAFT',btrim(p_outcome_summary),coalesce(p_outcome_payload,'{}'::jsonb),p_evidence_packet_id,p_actor_id,cw) returning * into r;
  update agriculture.trial set outcome_status='PARTIAL',updated_by=p_actor_id,updated_at=now() where trial_id=p_trial_id and outcome_status='NOT_RECORDED';
  return r;
end $$;


ALTER FUNCTION "agriculture"."api_record_outcome"("p_outcome_code" "text", "p_trial_id" "uuid", "p_outcome_type" "text", "p_outcome_summary" "text", "p_plot_id" "uuid", "p_outcome_payload" "jsonb", "p_evidence_packet_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."photo_analysis" (
    "photo_analysis_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "photo_evidence_id" "uuid" NOT NULL,
    "analysis_type" "text" NOT NULL,
    "analyzer_type" "text" NOT NULL,
    "analyzer_reference" "text",
    "analysis_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "observation_summary" "text" NOT NULL,
    "detected_features" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "anomaly_flags" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "confidence_status" "text" DEFAULT 'UNASSESSED'::"text" NOT NULL,
    "requires_human_review" boolean DEFAULT true NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_rationale" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "photo_analysis_analysis_status_check" CHECK (("analysis_status" = ANY (ARRAY['DRAFT'::"text", 'COMPLETED'::"text", 'REVIEWED'::"text", 'REJECTED'::"text"]))),
    CONSTRAINT "photo_analysis_analyzer_type_check" CHECK (("analyzer_type" = ANY (ARRAY['HUMAN'::"text", 'AI_MODEL'::"text", 'HYBRID'::"text"]))),
    CONSTRAINT "photo_analysis_confidence_status_check" CHECK (("confidence_status" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text"]))),
    CONSTRAINT "photo_analysis_review_consistency" CHECK (((("analysis_status" = 'REVIEWED'::"text") AND ("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL) AND ("review_rationale" IS NOT NULL)) OR ("analysis_status" = ANY (ARRAY['DRAFT'::"text", 'COMPLETED'::"text", 'REJECTED'::"text"])))),
    CONSTRAINT "photo_analysis_summary_not_blank" CHECK (("length"("btrim"("observation_summary")) > 0))
);


ALTER TABLE "agriculture"."photo_analysis" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_record_photo_analysis"("p_photo_evidence_id" "uuid", "p_analysis_type" "text", "p_analyzer_type" "text", "p_observation_summary" "text", "p_detected_features" "jsonb" DEFAULT '{}'::"jsonb", "p_anomaly_flags" "jsonb" DEFAULT '[]'::"jsonb", "p_confidence_status" "text" DEFAULT 'UNASSESSED'::"text", "p_analyzer_reference" "text" DEFAULT NULL::"text") RETURNS "agriculture"."photo_analysis"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.photo_analysis; BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.photo_evidence WHERE photo_evidence_id=p_photo_evidence_id AND review_status<>'REJECTED') THEN RAISE EXCEPTION 'USABLE_PHOTO_EVIDENCE_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.photo_analysis(photo_evidence_id,analysis_type,analyzer_type,analyzer_reference,analysis_status,observation_summary,detected_features,anomaly_flags,confidence_status,requires_human_review) VALUES(p_photo_evidence_id,p_analysis_type,p_analyzer_type,p_analyzer_reference,'COMPLETED',btrim(p_observation_summary),coalesce(p_detected_features,'{}'::jsonb),coalesce(p_anomaly_flags,'[]'::jsonb),p_confidence_status,true) RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_record_photo_analysis"("p_photo_evidence_id" "uuid", "p_analysis_type" "text", "p_analyzer_type" "text", "p_observation_summary" "text", "p_detected_features" "jsonb", "p_anomaly_flags" "jsonb", "p_confidence_status" "text", "p_analyzer_reference" "text") OWNER TO "postgres";


