    CONSTRAINT "photo_validation_result_validation_status_check" CHECK (("validation_status" = ANY (ARRAY['PASS'::"text", 'WARNING'::"text", 'FAIL'::"text", 'QUARANTINE'::"text", 'NOT_APPLICABLE'::"text"]))),
    CONSTRAINT "photo_validation_result_validation_type_check" CHECK (("validation_type" = ANY (ARRAY['FILE_TYPE'::"text", 'FILE_SIZE'::"text", 'DIMENSIONS'::"text", 'HASH_DUPLICATE'::"text", 'PERCEPTUAL_DUPLICATE'::"text", 'CAPTURE_TIME'::"text", 'GPS'::"text", 'TRIAL_CONTEXT'::"text", 'PLOT_CONTEXT'::"text", 'CROP_CONTEXT'::"text", 'SCALE_REFERENCE'::"text", 'IMAGE_QUALITY'::"text", 'EDITING_METADATA'::"text", 'OTHER'::"text"])))
);


ALTER TABLE "agriculture"."photo_validation_result" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_record_photo_validation"("p_photo_evidence_id" "uuid", "p_validation_type" "text", "p_validation_status" "text", "p_validation_summary" "text", "p_validation_context" "jsonb" DEFAULT '{}'::"jsonb", "p_requires_review" boolean DEFAULT false) RETURNS "agriculture"."photo_validation_result"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.photo_validation_result;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.photo_evidence WHERE photo_evidence_id=p_photo_evidence_id) THEN RAISE EXCEPTION 'PHOTO_EVIDENCE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 INSERT INTO agriculture.photo_validation_result(photo_evidence_id,validation_type,validation_status,validation_summary,validation_context,requires_review)
 VALUES(p_photo_evidence_id,p_validation_type,p_validation_status,btrim(p_validation_summary),COALESCE(p_validation_context,'{}'::jsonb),p_requires_review) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_record_photo_validation"("p_photo_evidence_id" "uuid", "p_validation_type" "text", "p_validation_status" "text", "p_validation_summary" "text", "p_validation_context" "jsonb", "p_requires_review" boolean) OWNER TO "postgres";


