    CONSTRAINT "reasoning_finding_confidence_status_check" CHECK (("confidence_status" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'CONTRADICTED'::"text"]))),
    CONSTRAINT "reasoning_finding_finding_type_check" CHECK (("finding_type" = ANY (ARRAY['MECHANISM'::"text", 'SUITABILITY'::"text", 'COMPATIBILITY'::"text", 'CONTRADICTION'::"text", 'CONFIDENCE'::"text", 'SAFETY'::"text", 'EVIDENCE_GAP'::"text", 'OTHER'::"text"])))
);


ALTER TABLE "agriculture"."reasoning_finding" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_record_reasoning_finding"("p_reasoning_run_id" "uuid", "p_finding_type" "text", "p_finding_summary" "text", "p_finding_detail" "jsonb" DEFAULT '{}'::"jsonb", "p_confidence_status" "text" DEFAULT 'UNASSESSED'::"text", "p_evidence_packet_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."reasoning_finding"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.reasoning_finding; BEGIN
 IF NOT EXISTS(SELECT 1 FROM agriculture.reasoning_run WHERE reasoning_run_id=p_reasoning_run_id AND run_status='RUNNING') THEN RAISE EXCEPTION 'REASONING_RUN_NOT_RUNNING' USING ERRCODE='55000'; END IF;
 INSERT INTO agriculture.reasoning_finding(reasoning_run_id,finding_type,finding_summary,finding_detail,confidence_status,evidence_packet_id) VALUES(p_reasoning_run_id,p_finding_type,btrim(p_finding_summary),COALESCE(p_finding_detail,'{}'::jsonb),p_confidence_status,p_evidence_packet_id) RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_record_reasoning_finding"("p_reasoning_run_id" "uuid", "p_finding_type" "text", "p_finding_summary" "text", "p_finding_detail" "jsonb", "p_confidence_status" "text", "p_evidence_packet_id" "uuid") OWNER TO "postgres";


