    "publication_date" "date",
    "jurisdiction" "text",
    "source_hash" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "evidence_source_source_type_check" CHECK (("source_type" = ANY (ARRAY['PEER_REVIEWED_PAPER'::"text", 'GOVERNMENT'::"text", 'STANDARD'::"text", 'PATENT'::"text", 'INSTITUTIONAL'::"text", 'SUPPLIER'::"text", 'HISTORICAL_DATASET'::"text", 'FIELD_EVIDENCE'::"text", 'OTHER'::"text"])))
);


ALTER TABLE "agriculture"."evidence_source" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_register_evidence_source"("p_source_type" "text", "p_title" "text", "p_citation" "text" DEFAULT NULL::"text", "p_source_url" "text" DEFAULT NULL::"text", "p_publication_date" "date" DEFAULT NULL::"date", "p_jurisdiction" "text" DEFAULT NULL::"text", "p_source_hash" "text" DEFAULT NULL::"text") RETURNS "agriculture"."evidence_source"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$
DECLARE r agriculture.evidence_source;
BEGIN
 IF nullif(btrim(p_title),'') IS NULL THEN RAISE EXCEPTION 'EVIDENCE_SOURCE_TITLE_REQUIRED' USING ERRCODE='23514'; END IF;
 IF p_source_url IS NULL AND p_citation IS NULL AND p_source_hash IS NULL THEN RAISE EXCEPTION 'EVIDENCE_SOURCE_REQUIRES_CITATION_URL_OR_HASH' USING ERRCODE='23514'; END IF;
 INSERT INTO agriculture.evidence_source(source_type,title,citation,source_url,publication_date,jurisdiction,source_hash)
 VALUES(p_source_type,btrim(p_title),p_citation,p_source_url,p_publication_date,p_jurisdiction,p_source_hash) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "agriculture"."api_register_evidence_source"("p_source_type" "text", "p_title" "text", "p_citation" "text", "p_source_url" "text", "p_publication_date" "date", "p_jurisdiction" "text", "p_source_hash" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "agriculture"."negative_learning_register" (
    "negative_learning_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "approved_learning_id" "uuid" NOT NULL,
    "suppression_scope" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "warning_text" "text" NOT NULL,
    "downstream_action" "text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "governance_decision_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    "country_workspace_id" "uuid",
    CONSTRAINT "negative_learning_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "negative_learning_register_downstream_action_check" CHECK (("downstream_action" = ANY (ARRAY['WARN'::"text", 'SUPPRESS'::"text", 'REJECT'::"text", 'ESCALATE_FOR_REVIEW'::"text"]))),
    CONSTRAINT "negative_learning_register_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['ACTIVE'::"text", 'SUSPENDED'::"text", 'SUPERSEDED'::"text", 'RETIRED'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "agriculture"."negative_learning_register" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_register_negative_learning"("p_approved_learning_id" "uuid", "p_suppression_scope" "jsonb", "p_warning_text" "text", "p_downstream_action" "text", "p_governance_decision_id" "uuid", "p_actor_id" "uuid") RETURNS "agriculture"."negative_learning_register"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.negative_learning_register; ds text; BEGIN SELECT decision_status INTO ds FROM agriculture.governance_decision WHERE decision_id=p_governance_decision_id; IF ds<>'APPROVED' OR p_actor_id IS NULL OR nullif(btrim(p_warning_text),'') IS NULL THEN RAISE EXCEPTION 'NEGATIVE_LEARNING_REQUIRES_APPROVED_GOVERNANCE_ACTOR_WARNING' USING ERRCODE='23514'; END IF; IF NOT EXISTS(SELECT 1 FROM agriculture.approved_learning WHERE approved_learning_id=p_approved_learning_id AND lifecycle_status='ACTIVE') THEN RAISE EXCEPTION 'ACTIVE_APPROVED_LEARNING_REQUIRED' USING ERRCODE='23514'; END IF; INSERT INTO agriculture.negative_learning_register(approved_learning_id,suppression_scope,warning_text,downstream_action,lifecycle_status,governance_decision_id,created_by) VALUES(p_approved_learning_id,coalesce(p_suppression_scope,'{}'::jsonb),btrim(p_warning_text),p_downstream_action,'ACTIVE',p_governance_decision_id,p_actor_id) RETURNING * INTO r; RETURN r; END; $$;


ALTER FUNCTION "agriculture"."api_register_negative_learning"("p_approved_learning_id" "uuid", "p_suppression_scope" "jsonb", "p_warning_text" "text", "p_downstream_action" "text", "p_governance_decision_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agriculture"."api_register_photo_evidence"("p_subject_entity_type" "text", "p_subject_entity_id" "uuid", "p_photo_type" "text", "p_storage_provider" "text", "p_storage_object_key" "text", "p_media_type" "text", "p_file_size_bytes" bigint, "p_image_hash_sha256" "text", "p_actor_id" "uuid", "p_original_filename" "text" DEFAULT NULL::"text", "p_width_pixels" integer DEFAULT NULL::integer, "p_height_pixels" integer DEFAULT NULL::integer, "p_perceptual_hash" "text" DEFAULT NULL::"text", "p_captured_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_capture_device" "text" DEFAULT NULL::"text", "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_scale_reference_present" boolean DEFAULT false, "p_input_submission_id" "uuid" DEFAULT NULL::"uuid") RETURNS "agriculture"."photo_evidence"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'agriculture', 'public'
    AS $$ DECLARE r agriculture.photo_evidence; code text; BEGIN
 IF p_actor_id IS NULL OR p_file_size_bytes<=0 OR nullif(btrim(p_image_hash_sha256),'') IS NULL THEN RAISE EXCEPTION 'PHOTO_REGISTRATION_REQUIRES_ACTOR_VALID_SIZE_AND_HASH' USING ERRCODE='23514'; END IF;
 IF p_media_type NOT IN ('image/jpeg','image/png','image/webp','image/heic','image/heif') THEN RAISE EXCEPTION 'UNSUPPORTED_PHOTO_MEDIA_TYPE' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM agriculture.photo_evidence WHERE image_hash_sha256=lower(btrim(p_image_hash_sha256))) THEN RAISE EXCEPTION 'DUPLICATE_PHOTO_HASH' USING ERRCODE='23505'; END IF;
 code:='PHOTO-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20));
 INSERT INTO agriculture.photo_evidence(photo_evidence_code,subject_entity_type,subject_entity_id,input_submission_id,photo_type,storage_provider,storage_object_key,original_filename,media_type,file_size_bytes,width_pixels,height_pixels,image_hash_sha256,perceptual_hash,captured_at,captured_by,upload_actor_id,capture_device,latitude,longitude,scale_reference_present,image_quality_status,context_validation_status,review_status,consent_usage_status)
 VALUES(code,upper(btrim(p_subject_entity_type)),p_subject_entity_id,p_input_submission_id,p_photo_type,p_storage_provider,p_storage_object_key,p_original_filename,p_media_type,p_file_size_bytes,p_width_pixels,p_height_pixels,lower(btrim(p_image_hash_sha256)),p_perceptual_hash,p_captured_at,p_actor_id,p_actor_id,p_capture_device,p_latitude,p_longitude,coalesce(p_scale_reference_present,false),'UNASSESSED','NOT_VALIDATED','PENDING','PENDING') RETURNING * INTO r; RETURN r; END; $$;


