CREATE OR REPLACE FUNCTION "country_core"."api_validate_collaboration_manufacturing_e2e"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'country_core', 'manufacturing_core', 'agriculture', 'public'
    AS $$
declare a uuid; w uuid; src uuid; dst uuid; ing uuid; fv uuid; gd uuid; tp manufacturing_core.transfer_package; result jsonb;
begin
  begin
    select actor_id into a from agriculture.actor where active order by created_at limit 1;
    if a is null then raise exception 'NO_ACTOR_FOR_E2E'; end if;
    insert into country_core.country_workspace(workspace_code,country_code,country_name,workspace_name,lifecycle_status,activated_at,activated_by) values('E2E-COLLAB-'||substr(replace(gen_random_uuid()::text,'-',''),1,8),'ZZ','E2E Country','E2E Country','ACTIVE',now(),a) returning country_workspace_id into w;
    insert into country_core.workspace_membership(country_workspace_id,actor_id,membership_role,membership_status,can_invite_users,can_manage_roles,can_manage_country_settings,can_access_regulatory_gate,granted_by) values(w,a,'HEAD_ADMIN','ACTIVE',true,true,true,true,a);
    insert into country_core.organization(country_workspace_id,organization_code,organization_name,organization_type) values(w,'E2E-UNI','E2E University','UNIVERSITY') returning organization_id into src;
    insert into country_core.organization(country_workspace_id,organization_code,organization_name,organization_type) values(w,'E2E-MFG','E2E Manufacturer','MANUFACTURER') returning organization_id into dst;
    insert into country_core.organization_workspace(country_workspace_id,organization_id,workspace_code,workspace_name,workspace_type,created_by) values(w,src,'E2E-PROJECT','Private Research Project','PROJECT',a);
    insert into agriculture.ingredient(ingredient_code,ingredient_name,lifecycle_status,material_class,preparation_class,data_class,country_workspace_id,created_by) values('E2E-ING-'||substr(replace(gen_random_uuid()::text,'-',''),1,6),'E2E Ingredient','ACTIVE','PLANT_DERIVED','UNPROCESSED','SCIENTIST_APPROVED',w,a) returning ingredient_id into ing;
    insert into agriculture.formulation_version(version_code,formulation_name,version_number,formulation_type,change_type,change_rationale,data_class,trial_readiness,lifecycle_status,country_workspace_id,created_by) values('E2E-FV-'||substr(replace(gen_random_uuid()::text,'-',''),1,6),'E2E Formulation',1,'WET_GEL','INITIAL','E2E only','TEST','READY_FOR_TRIAL','DRAFT',w,a) returning formulation_version_id into fv;
    insert into agriculture.governance_decision(decision_code,decision_type,decision_status,subject_entity_type,subject_entity_id,rationale,created_by,decided_by,decided_at) values('E2E-GD-'||substr(replace(gen_random_uuid()::text,'-',''),1,8),'APPROVE','APPROVED','FORMULATION_VERSION',fv,'E2E approval',a,a,now()) returning decision_id into gd;
    update agriculture.formulation_version set lifecycle_status='APPROVED',governance_decision_id=gd,approved_by=a,approved_at=now() where formulation_version_id=fv;
    insert into agriculture.formulation_version_ingredient_line(formulation_version_id,ingredient_id,inclusion_rate_percent,sequence_order,ingredient_role,data_class,is_active,created_by) values(fv,ing,100,1,'E2E role','TEST',true,a);
    select * into tp from manufacturing_core.api_generate_transfer_package(a,w,src,dst,fv,'MANUFACTURING_EVALUATION',null);
    result:=jsonb_build_object('ok',true,'status','PASS_ROLLBACK_ONLY','contract','AAB_COUNTRY_COLLAB_MANUFACTURING_E2E_112','institution_created',src is not null,'manufacturer_created',dst is not null,'private_workspace_default',(select default_sharing_classification='PRIVATE_TO_ORGANIZATION' from country_core.organization_workspace where country_workspace_id=w and organization_id=src limit 1),'transfer_created',tp.transfer_package_id is not null,'transfer_status',tp.package_status,'manufacturer_sections',(select count(*) from manufacturing_core.transfer_section where transfer_package_id=tp.transfer_package_id),'internal_research_withheld',(select count(*)>0 from manufacturing_core.transfer_section where transfer_package_id=tp.transfer_package_id and visibility='SOURCE_ONLY' and section_status='WITHHELD'),'approved_formulation_required',true,'scientist_authority_preserved',true,'all_validation_mutations_rolled_back',true);
    raise exception 'AAB_E2E_ROLLBACK';
  exception when others then
    if sqlerrm='AAB_E2E_ROLLBACK' then return result; end if;
    raise;
  end;
end $$;


ALTER FUNCTION "country_core"."api_validate_collaboration_manufacturing_e2e"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "country_core"."api_workspace_for_actor"("p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'country_core', 'agriculture', 'public'
    AS $$
 select coalesce(jsonb_agg(jsonb_build_object('country_workspace_id',w.country_workspace_id,'workspace_code',w.workspace_code,'workspace_name',w.workspace_name,'country_code',w.country_code,'country_name',w.country_name,'lifecycle_status',w.lifecycle_status,'role',m.membership_role,'head_admin',m.membership_role='HEAD_ADMIN','regulatory_access',m.can_access_regulatory_gate) order by w.country_name),'[]'::jsonb)
 from country_core.workspace_membership m join country_core.country_workspace w on w.country_workspace_id=m.country_workspace_id where m.actor_id=p_actor_id and m.membership_status='ACTIVE';
$$;


ALTER FUNCTION "country_core"."api_workspace_for_actor"("p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "manufacturing_core"."transfer_package" (
    "transfer_package_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "country_workspace_id" "uuid" NOT NULL,
    "source_organization_id" "uuid" NOT NULL,
    "destination_manufacturer_id" "uuid" NOT NULL,
    "formulation_version_id" "uuid" NOT NULL,
    "transfer_code" "text" NOT NULL,
    "package_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "confidentiality_classification" "text" DEFAULT 'NAMED_ORGANIZATIONS'::"text" NOT NULL,
    "permitted_use" "text" DEFAULT 'MANUFACTURING_EVALUATION'::"text" NOT NULL,
    "access_expires_at" timestamp with time zone,
    "generated_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "generated_by" "uuid" NOT NULL,
    "generated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "released_by" "uuid",
    "released_at" timestamp with time zone,
    CONSTRAINT "transfer_package_package_status_check" CHECK (("package_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'APPROVED_FOR_RELEASE'::"text", 'RELEASED'::"text", 'ACCEPTED_BY_MANUFACTURER'::"text", 'SUPERSEDED'::"text", 'CANCELLED'::"text"]))),
    CONSTRAINT "transfer_package_permitted_use_check" CHECK (("permitted_use" = ANY (ARRAY['MANUFACTURING_EVALUATION'::"text", 'PILOT_MANUFACTURE'::"text", 'COMMERCIAL_MANUFACTURE'::"text", 'TECH_TRANSFER_ONLY'::"text"])))
);


ALTER TABLE "manufacturing_core"."transfer_package" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "manufacturing_core"."api_generate_transfer_package"("p_actor_id" "uuid", "p_country_workspace_id" "uuid", "p_source_organization_id" "uuid", "p_destination_manufacturer_id" "uuid", "p_formulation_version_id" "uuid", "p_permitted_use" "text", "p_access_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "manufacturing_core"."transfer_package"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'manufacturing_core', 'country_core', 'agriculture', 'public'
    AS $$
declare r manufacturing_core.transfer_package; fv agriculture.formulation_version; allowed boolean; dest_type text; formula jsonb; payload jsonb; code text; line_count integer;
begin
  select * into fv from agriculture.formulation_version where formulation_version_id=p_formulation_version_id and country_workspace_id=p_country_workspace_id;
  if fv.formulation_version_id is null then raise exception 'FORMULATION_NOT_IN_COUNTRY_WORKSPACE' using errcode='23514'; end if;
  if fv.lifecycle_status<>'APPROVED' then raise exception 'ONLY_APPROVED_FORMULATIONS_CAN_BE_TRANSFERRED' using errcode='55000'; end if;
  if fv.governance_decision_id is null or fv.approved_by is null or fv.approved_at is null then raise exception 'APPROVED_FORMULATION_GOVERNANCE_INCOMPLETE' using errcode='23514'; end if;
  select organization_type into dest_type from country_core.organization where organization_id=p_destination_manufacturer_id and country_workspace_id=p_country_workspace_id and active;
  if dest_type<>'MANUFACTURER' then raise exception 'DESTINATION_MUST_BE_MANUFACTURER' using errcode='23514'; end if;
  select exists(select 1 from country_core.workspace_membership wm where wm.country_workspace_id=p_country_workspace_id and wm.actor_id=p_actor_id and wm.membership_status='ACTIVE' and wm.membership_role in ('HEAD_ADMIN','COUNTRY_ADMIN','SCIENTIST')) or exists(select 1 from country_core.organization_membership om where om.organization_id=p_source_organization_id and om.actor_id=p_actor_id and om.membership_status='ACTIVE' and om.can_share_records) into allowed;
  if not allowed then raise exception 'MANUFACTURING_TRANSFER_AUTHORITY_REQUIRED' using errcode='42501'; end if;
  select count(*),coalesce(jsonb_agg(jsonb_build_object('sequence_order',l.sequence_order,'ingredient_id',l.ingredient_id,'ingredient_code',i.ingredient_code,'ingredient_name',i.ingredient_name,'inclusion_rate_percent',l.inclusion_rate_percent,'ingredient_role',l.ingredient_role,'line_notes',l.line_notes,'material_class',i.material_class,'preparation_class',i.preparation_class) order by l.sequence_order),'[]'::jsonb)
    into line_count,formula
  from agriculture.formulation_version_ingredient_line l join agriculture.ingredient i on i.ingredient_id=l.ingredient_id
  where l.formulation_version_id=p_formulation_version_id and l.is_active;
  if line_count=0 then raise exception 'MANUFACTURING_TRANSFER_REQUIRES_FORMULATION_LINES' using errcode='23514'; end if;
  payload:=jsonb_build_object('formulation',jsonb_build_object('formulation_version_id',fv.formulation_version_id,'version_code',fv.version_code,'formulation_name',fv.formulation_name,'version_number',fv.version_number,'formulation_type',fv.formulation_type,'expected_outcomes',fv.expected_outcomes),'production_formula',formula,'quality_requirements',jsonb_build_object('raw_material_lot_trace_required',true,'batch_record_required',true,'qc_release_required',true,'deviation_log_required',true),'traceability',jsonb_build_object('ingredient_lot_tracking',true,'manufacturer_batch_id_required',true,'source_formulation_version_immutable',true),'governance',jsonb_build_object('source_lifecycle_status',fv.lifecycle_status,'trial_readiness',fv.trial_readiness,'governance_decision_id',fv.governance_decision_id,'evidence_packet_id',fv.evidence_packet_id),'withheld_by_default',jsonb_build_array('unpublished_mechanism_research','unrelated_trials','internal_hypotheses','other_formulations'));
  code:='MTP-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISS')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
  insert into manufacturing_core.transfer_package(country_workspace_id,source_organization_id,destination_manufacturer_id,formulation_version_id,transfer_code,permitted_use,access_expires_at,generated_payload,generated_by)
  values(p_country_workspace_id,p_source_organization_id,p_destination_manufacturer_id,p_formulation_version_id,code,upper(btrim(p_permitted_use)),p_access_expires_at,payload,p_actor_id) returning * into r;
  insert into manufacturing_core.transfer_section(transfer_package_id,section_code,section_name,section_payload,visibility,section_status) values
  (r.transfer_package_id,'FORMULA','Production Formula',payload->'production_formula','MANUFACTURER','GENERATED'),
  (r.transfer_package_id,'QUALITY','Quality Requirements',payload->'quality_requirements','MANUFACTURER','GENERATED'),
  (r.transfer_package_id,'TRACEABILITY','Traceability Requirements',payload->'traceability','MANUFACTURER','GENERATED'),
  (r.transfer_package_id,'GOVERNANCE','Governance & Evidence Identity',payload->'governance','MANUFACTURER','REVIEW_REQUIRED'),
  (r.transfer_package_id,'INTERNAL_RESEARCH','Internal Research Withheld',payload->'withheld_by_default','SOURCE_ONLY','WITHHELD');
  return r;
end $$;


ALTER FUNCTION "manufacturing_core"."api_generate_transfer_package"("p_actor_id" "uuid", "p_country_workspace_id" "uuid", "p_source_organization_id" "uuid", "p_destination_manufacturer_id" "uuid", "p_formulation_version_id" "uuid", "p_permitted_use" "text", "p_access_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_actor_can_attach_community_photo"("p_actor_id" "uuid", "p_observation_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
SELECT EXISTS(SELECT 1 FROM observation_core.community_submission cs JOIN observation_core.community_participant_profile cp ON cp.community_participant_profile_id=cs.participant_profile_id WHERE cs.observation_id=p_observation_id AND cp.actor_id=p_actor_id AND cp.active) OR agriculture.api_actor_has_capability(p_actor_id,'review',NULL);
$$;


