    "campaign_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_code" "text" NOT NULL,
    "campaign_name" "text" NOT NULL,
    "country_code" character(2),
    "primary_domain_code" "text" NOT NULL,
    "supporting_domain_codes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "campaign_question" "text" NOT NULL,
    "purpose" "text" NOT NULL,
    "target_locations" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "required_observations" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "participant_source_modes" "text"[] DEFAULT ARRAY['SCIENTIST'::"text", 'FIELD_TECHNICIAN'::"text"] NOT NULL,
    "photo_policy" "text" DEFAULT 'REQUIRED'::"text" NOT NULL,
    "start_date" "date",
    "end_date" "date",
    "lifecycle_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "created_by" "uuid",
    "reviewed_by" "uuid",
    "review_rationale" "text",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "campaign_dates_valid" CHECK ((("end_date" IS NULL) OR ("start_date" IS NULL) OR ("end_date" >= "start_date"))),
    CONSTRAINT "campaign_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'UNDER_REVIEW'::"text", 'ACTIVE'::"text", 'PAUSED'::"text", 'COMPLETED'::"text", 'REJECTED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "campaign_photo_policy_check" CHECK (("photo_policy" = ANY (ARRAY['REQUIRED'::"text", 'RECOMMENDED'::"text", 'OPTIONAL'::"text", 'NOT_APPLICABLE'::"text"]))),
    CONSTRAINT "campaign_purpose_required" CHECK (("length"("btrim"("purpose")) > 0)),
    CONSTRAINT "campaign_question_required" CHECK (("length"("btrim"("campaign_question")) > 0))
);


ALTER TABLE "observation_core"."campaign" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_create_campaign"("p_campaign_name" "text", "p_country_code" character, "p_primary_domain_code" "text", "p_campaign_question" "text", "p_purpose" "text", "p_actor_id" "uuid", "p_supporting_domain_codes" "text"[] DEFAULT '{}'::"text"[], "p_target_locations" "jsonb" DEFAULT '[]'::"jsonb", "p_required_observations" "jsonb" DEFAULT '[]'::"jsonb", "p_participant_source_modes" "text"[] DEFAULT ARRAY['SCIENTIST'::"text", 'FIELD_TECHNICIAN'::"text"], "p_photo_policy" "text" DEFAULT 'REQUIRED'::"text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS "observation_core"."campaign"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
DECLARE r observation_core.campaign;
BEGIN
 PERFORM agriculture.api_require_capability(p_actor_id,'create_draft',p_country_code);
 IF NOT EXISTS(SELECT 1 FROM observation_core.domain_adapter WHERE domain_code=upper(btrim(p_primary_domain_code)) AND enabled) THEN RAISE EXCEPTION 'ACTIVE_OBSERVATION_DOMAIN_ADAPTER_REQUIRED' USING ERRCODE='23514'; END IF;
 INSERT INTO observation_core.campaign(campaign_code,campaign_name,country_code,primary_domain_code,supporting_domain_codes,campaign_question,purpose,target_locations,required_observations,participant_source_modes,photo_policy,start_date,end_date,created_by)
 VALUES('CMP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20)),btrim(p_campaign_name),p_country_code,upper(btrim(p_primary_domain_code)),coalesce(p_supporting_domain_codes,'{}'),btrim(p_campaign_question),btrim(p_purpose),coalesce(p_target_locations,'[]'::jsonb),coalesce(p_required_observations,'[]'::jsonb),coalesce(p_participant_source_modes,ARRAY['SCIENTIST','FIELD_TECHNICIAN']),p_photo_policy,p_start_date,p_end_date,p_actor_id) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "observation_core"."api_create_campaign"("p_campaign_name" "text", "p_country_code" character, "p_primary_domain_code" "text", "p_campaign_question" "text", "p_purpose" "text", "p_actor_id" "uuid", "p_supporting_domain_codes" "text"[], "p_target_locations" "jsonb", "p_required_observations" "jsonb", "p_participant_source_modes" "text"[], "p_photo_policy" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "observation_core"."observation" (
    "observation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "observation_code" "text" NOT NULL,
    "domain_code" "text" NOT NULL,
    "country_code" character(2),
    "observation_type" "text" NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_reference" "text",
    "source_mode" "text" NOT NULL,
    "observer_actor_id" "uuid",
    "observed_at" timestamp with time zone NOT NULL,
    "latitude" numeric,
    "longitude" numeric,
    "location_accuracy_metres" numeric,
    "location_description" "text",
    "brief_description" "text" NOT NULL,
    "context_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'CAPTURED'::"text" NOT NULL,
    "trust_status" "text" DEFAULT 'UNASSESSED'::"text" NOT NULL,
    "evidence_status" "text" DEFAULT 'NOT_ELIGIBLE'::"text" NOT NULL,
    "input_submission_id" "uuid",
    "agriculture_observation_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    "archive_reason" "text",
    CONSTRAINT "observation_evidence_status_check" CHECK (("evidence_status" = ANY (ARRAY['NOT_ELIGIBLE'::"text", 'PENDING_REVIEW'::"text", 'ELIGIBLE_WITH_WARNINGS'::"text", 'ELIGIBLE'::"text"]))),
    CONSTRAINT "observation_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['CAPTURED'::"text", 'VALIDATING'::"text", 'QUARANTINED'::"text", 'UNDER_REVIEW'::"text", 'ACCEPTED'::"text", 'REJECTED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "observation_source_mode_check" CHECK (("source_mode" = ANY (ARRAY['SCIENTIST'::"text", 'FIELD_TECHNICIAN'::"text", 'FARMER'::"text", 'PUBLIC'::"text", 'STUDENT'::"text", 'TEACHER'::"text", 'INSTRUMENT'::"text", 'LABORATORY'::"text", 'EXTERNAL_SOURCE'::"text", 'SYSTEM'::"text"]))),
    CONSTRAINT "observation_trust_status_check" CHECK (("trust_status" = ANY (ARRAY['UNASSESSED'::"text", 'LOW'::"text", 'MODERATE'::"text", 'HIGH'::"text", 'VERIFIED'::"text"]))),
    CONSTRAINT "universal_observation_archive_consistency" CHECK (((("lifecycle_status" = 'ARCHIVED'::"text") AND ("archived_at" IS NOT NULL) AND ("archive_reason" IS NOT NULL)) OR ("lifecycle_status" <> 'ARCHIVED'::"text"))),
    CONSTRAINT "universal_observation_description_required" CHECK (("length"("btrim"("brief_description")) > 0)),
    CONSTRAINT "universal_observation_location_pair" CHECK (((("latitude" IS NULL) AND ("longitude" IS NULL)) OR ((("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)) AND (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))))
);


ALTER TABLE "observation_core"."observation" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_create_observation"("p_domain_code" "text", "p_country_code" character, "p_observation_type" "text", "p_subject_type" "text", "p_source_mode" "text", "p_observed_at" timestamp with time zone, "p_brief_description" "text", "p_actor_id" "uuid", "p_subject_reference" "text" DEFAULT NULL::"text", "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_location_accuracy_metres" numeric DEFAULT NULL::numeric, "p_location_description" "text" DEFAULT NULL::"text", "p_context_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "observation_core"."observation"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
DECLARE r observation_core.observation; c text; a observation_core.domain_adapter; sm text:=upper(btrim(p_source_mode));
BEGIN
 c:=upper(btrim(p_domain_code)); SELECT * INTO a FROM observation_core.domain_adapter WHERE domain_code=c;
 IF a.domain_code IS NULL THEN RAISE EXCEPTION 'OBSERVATION_DOMAIN_ADAPTER_NOT_FOUND: %',c USING ERRCODE='23514'; END IF;
 IF NOT a.enabled THEN RAISE EXCEPTION 'OBSERVATION_DOMAIN_ADAPTER_DISABLED: %',c USING ERRCODE='42501'; END IF;
 IF NOT sm=ANY(a.allowed_source_modes) THEN RAISE EXCEPTION 'OBSERVATION_SOURCE_MODE_NOT_ALLOWED_FOR_DOMAIN' USING ERRCODE='23514'; END IF;
 IF p_actor_id IS NULL OR NOT (agriculture.api_actor_has_capability(p_actor_id,'create_draft',p_country_code) OR (sm IN ('FARMER','PUBLIC','STUDENT','TEACHER') AND agriculture.api_actor_has_capability(p_actor_id,'community_capture',p_country_code))) THEN RAISE EXCEPTION 'OBSERVATION_CREATE_CAPABILITY_DENIED' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_brief_description),'') IS NULL THEN RAISE EXCEPTION 'OBSERVATION_DESCRIPTION_REQUIRED' USING ERRCODE='23514'; END IF;
 IF a.location_policy='REQUIRED' AND (p_latitude IS NULL OR p_longitude IS NULL) THEN RAISE EXCEPTION 'OBSERVATION_LOCATION_REQUIRED_FOR_DOMAIN' USING ERRCODE='23514'; END IF;
 INSERT INTO observation_core.observation(observation_code,domain_code,country_code,observation_type,subject_type,subject_reference,source_mode,observer_actor_id,observed_at,latitude,longitude,location_accuracy_metres,location_description,brief_description,context_payload) VALUES('OBS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20)),c,p_country_code,upper(btrim(p_observation_type)),upper(btrim(p_subject_type)),p_subject_reference,sm,p_actor_id,p_observed_at,p_latitude,p_longitude,p_location_accuracy_metres,p_location_description,btrim(p_brief_description),coalesce(p_context_payload,'{}'::jsonb)) RETURNING * INTO r;
 RETURN r;
END; $$;


ALTER FUNCTION "observation_core"."api_create_observation"("p_domain_code" "text", "p_country_code" character, "p_observation_type" "text", "p_subject_type" "text", "p_source_mode" "text", "p_observed_at" timestamp with time zone, "p_brief_description" "text", "p_actor_id" "uuid", "p_subject_reference" "text", "p_latitude" numeric, "p_longitude" numeric, "p_location_accuracy_metres" numeric, "p_location_description" "text", "p_context_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_decide_campaign"("p_campaign_id" "uuid", "p_decision" "text", "p_rationale" "text", "p_actor_id" "uuid") RETURNS "observation_core"."campaign"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
DECLARE r observation_core.campaign; d text:=upper(btrim(p_decision));
BEGIN
 PERFORM agriculture.api_require_capability(p_actor_id,'review',NULL);
 IF d NOT IN ('APPROVE','REJECT') OR nullif(btrim(p_rationale),'') IS NULL THEN RAISE EXCEPTION 'CAMPAIGN_REVIEW_REQUIRES_DECISION_AND_RATIONALE' USING ERRCODE='23514'; END IF;
 UPDATE observation_core.campaign SET lifecycle_status=CASE WHEN d='APPROVE' THEN 'ACTIVE' ELSE 'REJECTED' END,reviewed_by=p_actor_id,review_rationale=btrim(p_rationale),reviewed_at=now(),updated_at=now() WHERE campaign_id=p_campaign_id AND lifecycle_status='UNDER_REVIEW' RETURNING * INTO r;
 IF r.campaign_id IS NULL THEN RAISE EXCEPTION 'CAMPAIGN_NOT_UNDER_REVIEW' USING ERRCODE='55000'; END IF;
 RETURN r;
END; $$;


ALTER FUNCTION "observation_core"."api_decide_campaign"("p_campaign_id" "uuid", "p_decision" "text", "p_rationale" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "observation_core"."community_submission" (
    "community_submission_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "submission_code" "text" NOT NULL,
    "observation_id" "uuid" NOT NULL,
    "participant_profile_id" "uuid" NOT NULL,
    "campaign_id" "uuid",
    "user_category_hint" "text",
    "user_identification_text" "text",
    "photo_required" boolean DEFAULT true NOT NULL,
    "location_required" boolean DEFAULT true NOT NULL,
    "consent_confirmed" boolean NOT NULL,
    "offline_capture_id" "text",
    "client_captured_at" timestamp with time zone,
    "client_app_version" "text",
    "low_bandwidth_mode" boolean DEFAULT false NOT NULL,
    "submission_status" "text" DEFAULT 'AWAITING_PHOTO'::"text" NOT NULL,
    "submitted_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "review_summary" "text",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "community_submission_submission_status_check" CHECK (("submission_status" = ANY (ARRAY['AWAITING_PHOTO'::"text", 'READY_TO_SUBMIT'::"text", 'SUBMITTED'::"text", 'VALIDATING'::"text", 'QUARANTINED'::"text", 'UNDER_REVIEW'::"text", 'ACCEPTED'::"text", 'REJECTED'::"text"])))
);


ALTER TABLE "observation_core"."community_submission" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_finalize_community_submission"("p_community_submission_id" "uuid", "p_actor_id" "uuid") RETURNS "observation_core"."community_submission"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
DECLARE r observation_core.community_submission; photo_count integer;
BEGIN
 SELECT count(*) INTO photo_count FROM observation_core.community_submission cs JOIN observation_core.evidence_link el ON el.observation_id=cs.observation_id WHERE cs.community_submission_id=p_community_submission_id AND el.evidence_type='PHOTO';
 IF photo_count=0 THEN RAISE EXCEPTION 'COMMUNITY_PHOTO_REQUIRED' USING ERRCODE='23514'; END IF;
 UPDATE observation_core.community_submission cs SET submission_status='SUBMITTED',submitted_at=now() FROM observation_core.community_participant_profile cp WHERE cs.community_submission_id=p_community_submission_id AND cs.participant_profile_id=cp.community_participant_profile_id AND cp.actor_id=p_actor_id AND cs.submission_status IN ('AWAITING_PHOTO','READY_TO_SUBMIT') RETURNING cs.* INTO r;
 IF r.community_submission_id IS NULL THEN RAISE EXCEPTION 'COMMUNITY_SUBMISSION_NOT_FINALISABLE' USING ERRCODE='55000'; END IF;
 UPDATE observation_core.observation SET lifecycle_status='VALIDATING',updated_at=now() WHERE observation_id=r.observation_id;
 RETURN r;
END; $$;


ALTER FUNCTION "observation_core"."api_finalize_community_submission"("p_community_submission_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_find_offline_capture"("p_actor_id" "uuid", "p_offline_capture_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
SELECT coalesce((SELECT jsonb_build_object('community_submission',to_jsonb(cs),'observation',to_jsonb(o)) FROM observation_core.community_submission cs JOIN observation_core.community_participant_profile cp ON cp.community_participant_profile_id=cs.participant_profile_id JOIN observation_core.observation o ON o.observation_id=cs.observation_id WHERE cp.actor_id=p_actor_id AND cs.offline_capture_id=p_offline_capture_id LIMIT 1),'null'::jsonb);
$$;


ALTER FUNCTION "observation_core"."api_find_offline_capture"("p_actor_id" "uuid", "p_offline_capture_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_get_community_photo_metadata"("p_actor_id" "uuid", "p_photo_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'observation_core', 'agriculture', 'public'
    AS $$
DECLARE allowed boolean:=false; result jsonb;
BEGIN
 SELECT EXISTS(
   SELECT 1 FROM agriculture.photo_evidence pe
   JOIN observation_core.evidence_link el ON el.photo_evidence_id=pe.photo_evidence_id
   JOIN observation_core.observation o ON o.observation_id=el.observation_id
   LEFT JOIN observation_core.community_submission cs ON cs.observation_id=o.observation_id
   LEFT JOIN observation_core.community_participant_profile cp ON cp.community_participant_profile_id=cs.participant_profile_id
   WHERE pe.photo_evidence_id=p_photo_evidence_id AND (cp.actor_id=p_actor_id OR agriculture.api_actor_has_capability(p_actor_id,'review',NULL))
 ) INTO allowed;
 IF NOT allowed THEN RAISE EXCEPTION 'COMMUNITY_PHOTO_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 SELECT jsonb_build_object('photo_evidence_id',pe.photo_evidence_id,'storage_provider',pe.storage_provider,'storage_object_key',pe.storage_object_key,'original_filename',pe.original_filename,'media_type',pe.media_type,'file_size_bytes',pe.file_size_bytes,'image_quality_status',pe.image_quality_status,'context_validation_status',pe.context_validation_status,'review_status',pe.review_status,'consent_usage_status',pe.consent_usage_status) INTO result FROM agriculture.photo_evidence pe WHERE pe.photo_evidence_id=p_photo_evidence_id;
 RETURN result;
END; $$;


ALTER FUNCTION "observation_core"."api_get_community_photo_metadata"("p_actor_id" "uuid", "p_photo_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "observation_core"."api_get_community_profile"("p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
