    CONSTRAINT "campaign_observation_contribution_status_check" CHECK (("contribution_status" = ANY (ARRAY['SUBMITTED'::"text", 'ACCEPTED'::"text", 'REJECTED'::"text", 'DUPLICATE'::"text"])))
);


