CREATE OR REPLACE FUNCTION "public"."aab_claim_country_activation"("p_activation_code" "text", "p_workspace_name" "text" DEFAULT NULL::"text", "p_default_language" "text" DEFAULT 'en'::"text", "p_timezone_name" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'platform', 'country_core', 'agriculture', 'extensions', 'auth'
    AS $$
declare
  v_email text;
  v_activation country_core.country_activation;
  v_actor_id uuid;
  v_workspace country_core.country_workspace;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATED_VERIFIED_EMAIL_REQUIRED' using errcode='28000';
  end if;
  select lower(btrim(u.email)) into v_email
  from auth.users u
  where u.id = auth.uid()
    and u.email_confirmed_at is not null
    and u.deleted_at is null
    and coalesce(u.is_anonymous, false) is false;
  if coalesce(v_email, '') = '' then
    raise exception 'AUTHENTICATED_VERIFIED_EMAIL_REQUIRED' using errcode='28000';
  end if;
  if length(coalesce(p_activation_code,'')) < 8 then
    raise exception 'INVALID_OR_EXPIRED_COUNTRY_ACTIVATION' using errcode='28000';
  end if;

  select a.* into v_activation
  from country_core.country_activation a
  where a.activation_status='ISSUED'
    and a.expires_at>now()
    and lower(a.nominated_head_admin_email)=v_email
    and extensions.crypt(p_activation_code,a.activation_code_hash)=a.activation_code_hash
  order by a.issued_at desc limit 1;
  if v_activation.country_activation_id is null then
    raise exception 'INVALID_OR_EXPIRED_COUNTRY_ACTIVATION' using errcode='28000';
  end if;

  v_actor_id := platform.create_actor_for_current_user('ADMIN');
  v_workspace := country_core.api_activate_country(v_activation.country_code,p_activation_code,v_actor_id,p_workspace_name,p_default_language,p_timezone_name);
  insert into platform.entry_audit_event(auth_user_id,actor_id,event_code,outcome_code,route_code,country_workspace_id)
  values(auth.uid(),v_actor_id,'COUNTRY_ACTIVATION_CLAIM','ALLOWED','COUNTRY_SETTINGS',v_workspace.country_workspace_id);
  return jsonb_build_object('ok',true,'route','/aab-local/app/_rebuild/settings.html','route_code','COUNTRY_SETTINGS');
exception when others then
  insert into platform.entry_audit_event(auth_user_id,actor_id,event_code,outcome_code,reason)
  values(auth.uid(),platform.current_actor_id(),'COUNTRY_ACTIVATION_CLAIM','DENIED',sqlerrm);
  raise;
end
$$;


ALTER FUNCTION "public"."aab_claim_country_activation"("p_activation_code" "text", "p_workspace_name" "text", "p_default_language" "text", "p_timezone_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aab_resolve_entry"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'platform', 'country_core', 'agriculture', 'auth'
    AS $$
declare v_actor_id uuid; v_ws country_core.workspace_membership; v_org country_core.organization_membership; v_route text; v_route_code text;
begin
 if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='28000'; end if;
 v_actor_id:=platform.current_actor_id();
 if v_actor_id is null then return jsonb_build_object('ok',false,'state','CLAIM_REQUIRED','route','/enter-aab'); end if;
 if platform.is_platform_admin(v_actor_id) then
   v_route:='/aab-local/app/_rebuild/aab-admin.html'; v_route_code:='AAB_PLATFORM_ADMIN_DASHBOARD';
 else
   select * into v_ws from country_core.workspace_membership m where m.actor_id=v_actor_id and m.membership_status='ACTIVE'
   order by case m.membership_role when 'HEAD_ADMIN' then 0 when 'COUNTRY_ADMIN' then 1 else 2 end,m.granted_at limit 1;
   if v_ws.workspace_membership_id is null then v_route:='/aab-local/app/_rebuild/my-dashboard.html';v_route_code:='PERSONAL_DASHBOARD';
   elsif v_ws.membership_role='HEAD_ADMIN' and exists(select 1 from country_core.country_workspace w where w.country_workspace_id=v_ws.country_workspace_id and w.lifecycle_status in ('PROVISIONED','SETUP_PENDING')) then v_route:='/aab-local/app/_rebuild/settings.html';v_route_code:='COUNTRY_SETTINGS';
   else
     select * into v_org from country_core.organization_membership o where o.actor_id=v_actor_id and o.membership_status='ACTIVE' order by o.granted_at limit 1;
     if v_org.organization_membership_id is not null and v_org.can_manage_organization and not exists(select 1 from country_core.institution_scientific_settings s where s.organization_id=v_org.organization_id and s.setup_status='CONFIGURED') then v_route:='/aab-local/app/_rebuild/institution-setup.html';v_route_code:='INSTITUTION_SETTINGS';
     elsif v_ws.membership_role in ('HEAD_ADMIN','COUNTRY_ADMIN') then v_route:='/aab-local/app/_rebuild/country-admin.html';v_route_code:='COUNTRY_DASHBOARD';
     else v_route:='/aab-local/app/_rebuild/my-dashboard.html';v_route_code:='ROLE_DASHBOARD'; end if;
   end if;
 end if;
 insert into platform.entry_audit_event(auth_user_id,actor_id,event_code,outcome_code,route_code,country_workspace_id,organization_id)
 values(auth.uid(),v_actor_id,'ENTRY_RESOLUTION','ALLOWED',v_route_code,v_ws.country_workspace_id,v_org.organization_id);
 return jsonb_build_object('ok',true,'state','ROUTE_APPROVED','route',v_route,'route_code',v_route_code);
end $$;


ALTER FUNCTION "public"."aab_resolve_entry"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."aab_resolve_entry"() IS 'Returns only a server-approved relative entry route derived from protected identity and membership records.';



CREATE OR REPLACE FUNCTION "public"."aab_submit_country_participation_request"("p_request" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_user auth.users%rowtype; v_id uuid; v_reference text; v_domains text[];
begin
  if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
  select * into v_user from auth.users where id = auth.uid();
  if v_user.id is null or v_user.email_confirmed_at is null then raise exception 'VERIFIED_EMAIL_REQUIRED'; end if;
  if lower(coalesce(p_request->>'official_email','')) <> lower(coalesce(v_user.email,'')) then raise exception 'EMAIL_MISMATCH'; end if;
  if coalesce((p_request->>'authority_declared')::boolean,false) is not true then raise exception 'AUTHORITY_DECLARATION_REQUIRED'; end if;
  select coalesce(array_agg(value),array[]::text[]) into v_domains from jsonb_array_elements_text(coalesce(p_request->'domains','[]'::jsonb));
  if cardinality(v_domains) < 1 or cardinality(v_domains) > 7 then raise exception 'INVALID_DOMAINS'; end if;
  if coalesce(p_request->>'organisation_type','') = '' or coalesce(p_request->>'position_category','') = '' then raise exception 'CONTROLLED_FIELDS_REQUIRED'; end if;
  v_id := gen_random_uuid(); v_reference := 'AAB-REQ-' || upper(substr(replace(v_id::text,'-',''),1,10));
  insert into public.aab_country_participation_requests (
    id,reference,applicant_user_id,country_name,jurisdiction_level,jurisdiction_name,organisation_name,
    organisation_type,applicant_name,official_position,position_category,official_email,official_website,
    applicant_capacity,domains,proposed_purpose,supporting_information,authority_declared,email_verified
  ) values (
    v_id,v_reference,auth.uid(),left(trim(p_request->>'country_name'),120),p_request->>'jurisdiction_level',
    nullif(left(trim(p_request->>'jurisdiction_name'),160),''),left(trim(p_request->>'organisation_name'),200),
    left(trim(p_request->>'organisation_type'),120),left(trim(p_request->>'applicant_name'),160),
    left(trim(p_request->>'official_position'),160),left(trim(p_request->>'position_category'),120),lower(v_user.email),
    nullif(left(trim(p_request->>'official_website'),500),''),left(trim(p_request->>'applicant_capacity'),160),v_domains,
    left(trim(p_request->>'proposed_purpose'),4000),nullif(left(trim(p_request->>'supporting_information'),4000),''),true,true
  );
  return jsonb_build_object('ok',true,'reference',v_reference,'status','PENDING_REVIEW');
exception when unique_violation then raise exception 'REQUEST_REFERENCE_COLLISION'; end;
$$;


ALTER FUNCTION "public"."aab_submit_country_participation_request"("p_request" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "regulatory_core"."api_actor_can_access_regulatory"("p_actor_id" "uuid", "p_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'country_core', 'agriculture', 'public'
    AS $$
 select exists(select 1 from country_core.workspace_membership m where m.actor_id=p_actor_id and m.country_workspace_id=p_workspace_id and m.membership_status='ACTIVE' and (m.membership_role='HEAD_ADMIN' or (m.membership_role='REGULATORY_ADMIN' and m.can_access_regulatory_gate)));
$$;


ALTER FUNCTION "regulatory_core"."api_actor_can_access_regulatory"("p_actor_id" "uuid", "p_workspace_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "regulatory_core"."dossier_passport" (
    "dossier_passport_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "country_workspace_id" "uuid" NOT NULL,
    "passport_code" "text" NOT NULL,
    "passport_name" "text" NOT NULL,
    "subject_entity_type" "text" NOT NULL,
    "subject_entity_id" "uuid" NOT NULL,
    "product_category" "text" NOT NULL,
    "passport_status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "ownership_summary" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "dossier_passport_passport_status_check" CHECK (("passport_status" = ANY (ARRAY['DRAFT'::"text", 'ASSEMBLING'::"text", 'READY_FOR_ASSESSMENT'::"text", 'ACTIVE'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "regulatory_core"."dossier_passport" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "regulatory_core"."api_create_dossier_passport"("p_workspace_id" "uuid", "p_passport_name" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_product_category" "text", "p_actor_id" "uuid") RETURNS "regulatory_core"."dossier_passport"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'regulatory_core', 'country_core', 'agriculture', 'public'
    AS $$
declare r regulatory_core.dossier_passport; w country_core.country_workspace;
begin
 if not regulatory_core.api_actor_can_access_regulatory(p_actor_id,p_workspace_id) then raise exception 'REGULATORY_GATE_AUTHORITY_REQUIRED' using errcode='42501'; end if;
 select * into w from country_core.country_workspace where country_workspace_id=p_workspace_id;
 insert into regulatory_core.dossier_passport(country_workspace_id,passport_code,passport_name,subject_entity_type,subject_entity_id,product_category,created_by)
 values(p_workspace_id,'DSP-'||w.country_code||'-'||upper(substr(gen_random_uuid()::text,1,8)),btrim(p_passport_name),upper(btrim(p_subject_type)),p_subject_id,btrim(p_product_category),p_actor_id) returning * into r;
 insert into country_core.regulatory_access_event(country_workspace_id,actor_id,event_type,event_summary) values(p_workspace_id,p_actor_id,'DOSSIER_OPENED','Created Dossier Passport '||r.passport_code);
 return r;
end $$;


ALTER FUNCTION "regulatory_core"."api_create_dossier_passport"("p_workspace_id" "uuid", "p_passport_name" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_product_category" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "regulatory_core"."api_regulatory_context"("p_actor_id" "uuid", "p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'regulatory_core', 'country_core', 'agriculture', 'public'
    AS $$
declare allowed boolean; result jsonb;
begin
 allowed:=regulatory_core.api_actor_can_access_regulatory(p_actor_id,p_workspace_id);
 if not allowed then raise exception 'REGULATORY_GATE_AUTHORITY_REQUIRED' using errcode='42501'; end if;
 select jsonb_build_object(
  'gate',(select to_jsonb(g) from country_core.regulatory_security_gate g where g.country_workspace_id=p_workspace_id),
  'workspace',(select jsonb_build_object('country_workspace_id',w.country_workspace_id,'country_code',w.country_code,'country_name',w.country_name,'workspace_name',w.workspace_name) from country_core.country_workspace w where w.country_workspace_id=p_workspace_id),
  'passports',coalesce((select jsonb_agg(to_jsonb(p) order by p.updated_at desc) from regulatory_core.v_dossier_passport_summary p where p.country_workspace_id=p_workspace_id),'[]'::jsonb),
  'jurisdictions',coalesce((select jsonb_agg(to_jsonb(j) order by j.jurisdiction_name) from regulatory_core.jurisdiction j where j.active),'[]'::jsonb),
  'verified_sources',(select count(*) from regulatory_core.regulatory_source where verification_status='VERIFIED_CURRENT'),
  'active_requirements',(select count(*) from regulatory_core.regulatory_requirement where lifecycle_status='ACTIVE'),
  'recent_changes',coalesce((select jsonb_agg(to_jsonb(c) order by c.detected_at desc) from (select * from regulatory_core.regulatory_change_event order by detected_at desc limit 25)c),'[]'::jsonb)
 ) into result;
 return result;
end $$;


ALTER FUNCTION "regulatory_core"."api_regulatory_context"("p_actor_id" "uuid", "p_workspace_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "regulatory_core"."translation_run" (
    "translation_run_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "dossier_passport_id" "uuid" NOT NULL,
    "destination_jurisdiction_code" "text" NOT NULL,
    "run_status" "text" DEFAULT 'RUNNING'::"text" NOT NULL,
    "rules_effective_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "readiness_percent" numeric,
    "reusable_requirements" integer DEFAULT 0 NOT NULL,
    "partial_requirements" integer DEFAULT 0 NOT NULL,
    "missing_requirements" integer DEFAULT 0 NOT NULL,
    "local_study_requirements" integer DEFAULT 0 NOT NULL,
    "regulator_confirmation_requirements" integer DEFAULT 0 NOT NULL,
    "assessment_summary" "text",
    "initiated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "translation_run_readiness_percent_check" CHECK ((("readiness_percent" >= (0)::numeric) AND ("readiness_percent" <= (100)::numeric))),
    CONSTRAINT "translation_run_run_status_check" CHECK (("run_status" = ANY (ARRAY['RUNNING'::"text", 'COMPLETE'::"text", 'BLOCKED'::"text", 'FAILED'::"text"])))
);


ALTER TABLE "regulatory_core"."translation_run" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "regulatory_core"."api_run_dossier_translation"("p_passport_id" "uuid", "p_destination_jurisdiction" "text", "p_actor_id" "uuid") RETURNS "regulatory_core"."translation_run"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'regulatory_core', 'country_core', 'agriculture', 'public'
    AS $$
declare p regulatory_core.dossier_passport; r regulatory_core.translation_run; total_n int; assessed_n int; complete_n int; partial_n int; missing_n int; local_n int; confirm_n int;
begin
 select * into p from regulatory_core.dossier_passport where dossier_passport_id=p_passport_id;
 if p.dossier_passport_id is null then raise exception 'DOSSIER_NOT_FOUND'; end if;
 if not regulatory_core.api_actor_can_access_regulatory(p_actor_id,p.country_workspace_id) then raise exception 'REGULATORY_GATE_AUTHORITY_REQUIRED' using errcode='42501'; end if;
 insert into regulatory_core.translation_run(dossier_passport_id,destination_jurisdiction_code,initiated_by) values(p_passport_id,p_destination_jurisdiction,p_actor_id) returning * into r;
 select count(*) into total_n from regulatory_core.regulatory_requirement q join regulatory_core.regulatory_source s on s.regulatory_source_id=q.regulatory_source_id where q.jurisdiction_code=p_destination_jurisdiction and q.lifecycle_status='ACTIVE' and s.verification_status='VERIFIED_CURRENT' and (q.effective_from is null or q.effective_from<=current_date) and (q.effective_to is null or q.effective_to>=current_date);
 if total_n=0 then
   update regulatory_core.translation_run set run_status='BLOCKED',assessment_summary='No verified current regulatory requirements are loaded for this jurisdiction. AAB will not invent dossier readiness.',completed_at=now() where translation_run_id=r.translation_run_id returning * into r;
   return r;
 end if;
 -- Requirement matching is deliberately not guessed. Each requirement begins MISSING/LOCAL-STUDY until evidence mapping is explicitly implemented/reviewed.
 insert into regulatory_core.requirement_assessment(translation_run_id,regulatory_requirement_id,assessment_status,gap_summary,assessment_rationale)
 select r.translation_run_id,q.regulatory_requirement_id,case when q.local_study_required then 'REQUIRES_LOCAL_STUDY' else 'MISSING' end,'No governed dossier evidence has yet been mapped to this requirement.','Fail-closed initial assessment; evidence must be mapped and reviewed.'
 from regulatory_core.regulatory_requirement q join regulatory_core.regulatory_source s on s.regulatory_source_id=q.regulatory_source_id where q.jurisdiction_code=p_destination_jurisdiction and q.lifecycle_status='ACTIVE' and s.verification_status='VERIFIED_CURRENT' and (q.effective_from is null or q.effective_from<=current_date) and (q.effective_to is null or q.effective_to>=current_date);
 select count(*) filter(where assessment_status='COMPLETE'),count(*) filter(where assessment_status='PARTIAL'),count(*) filter(where assessment_status='MISSING'),count(*) filter(where assessment_status='REQUIRES_LOCAL_STUDY'),count(*) filter(where assessment_status='REQUIRES_REGULATOR_CONFIRMATION') into complete_n,partial_n,missing_n,local_n,confirm_n from regulatory_core.requirement_assessment where translation_run_id=r.translation_run_id;
 update regulatory_core.translation_run set run_status='COMPLETE',readiness_percent=round((complete_n + partial_n*0.5)::numeric/total_n*100,1),reusable_requirements=complete_n,partial_requirements=partial_n,missing_requirements=missing_n,local_study_requirements=local_n,regulator_confirmation_requirements=confirm_n,assessment_summary='Initial fail-closed dossier translation against verified current requirements. Missing evidence is not inferred as complete.',completed_at=now() where translation_run_id=r.translation_run_id returning * into r;
 return r;
end $$;


ALTER FUNCTION "regulatory_core"."api_run_dossier_translation"("p_passport_id" "uuid", "p_destination_jurisdiction" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security_core"."api_run_security_brain"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security_core', 'platform', 'agriculture', 'public'
    AS $$
declare
  v_actor uuid;
  v_run uuid;
  v_created integer := 0;
  v_resolved integer := 0;
  v_rows integer := 0;
  v_count integer := 0;
  v_fingerprint text;
  v_request record;
begin
  v_actor := platform.current_actor_id();
  if v_actor is null or not platform.is_platform_admin(v_actor) then
    raise exception 'AAB_PLATFORM_ADMIN_REQUIRED' using errcode = '42501';
  end if;

  insert into security_core.security_brain_run(initiated_by)
  values (v_actor)
  returning run_id into v_run;

  select count(*) into v_count
  from platform.entry_audit_event
  where outcome_code <> 'ALLOWED'
    and occurred_at > now() - interval '15 minutes';

  if v_count >= 5 then
    v_fingerprint := 'REPEATED_ENTRY_DENIALS:' ||
      to_char(date_trunc('hour', now()), 'YYYYMMDDHH24');

    insert into security_core.security_alert(
      alert_fingerprint,
      alert_type,
      severity,
      confidence_status,
      title,
      explanation,
      evidence_summary,
      recommended_response
    )
    values (
      v_fingerprint,
      'REPEATED_ENTRY_DENIALS',
      'HIGH',
      'HIGH',
      'Repeated protected-entry denials',
      'Five or more fail-closed entry decisions occurred within fifteen minutes.',
      jsonb_build_object('denied_count', v_count, 'window_minutes', 15),
      'Review affected identities and source context. Do not change access without human verification.'
    )
    on conflict (alert_fingerprint) do nothing;

    get diagnostics v_rows = row_count;
    v_created := v_created + v_rows;

    update security_core.security_alert
    set evidence_summary = jsonb_build_object('denied_count', v_count, 'window_minutes', 15),
        explanation = 'Five or more fail-closed entry decisions occurred within fifteen minutes.',
        recommended_response = 'Review affected identities and source context. Do not change access without human verification.'
    where alert_fingerprint = v_fingerprint
      and alert_status = 'OPEN';
  end if;

  for v_request in
    select id, reference, country_name, jurisdiction_level, organisation_name, submitted_at
    from public.aab_country_participation_requests
    where review_status = 'PENDING_REVIEW'
  loop
    v_fingerprint := 'PARTICIPATION_REVIEW_PENDING:' || v_request.id::text;

    insert into security_core.security_alert(
      alert_fingerprint,
      alert_type,
      severity,
      confidence_status,
      title,
      explanation,
      evidence_summary,
      recommended_response
    )
    values (
      v_fingerprint,
      'PARTICIPATION_REVIEW_PENDING',
      'INFORMATION',
      'HIGH',
      'Governed participation review pending',
      'A verified participation request remains pending a governed human decision.',
      jsonb_build_object(
        'request_id', v_request.id,
        'reference', v_request.reference,
        'country_name', v_request.country_name,
        'jurisdiction_level', v_request.jurisdiction_level,
        'organisation_name', v_request.organisation_name,
        'review_status', 'PENDING_REVIEW',
        'submitted_at', v_request.submitted_at
      ),
      'An authorised Platform Owner or support reviewer should assess the evidence and record a decision with rationale. Approval must remain separate from country provisioning.'
    )
    on conflict (alert_fingerprint) do nothing;

    get diagnostics v_rows = row_count;
    v_created := v_created + v_rows;

    update security_core.security_alert
    set evidence_summary = jsonb_build_object(
          'request_id', v_request.id,
          'reference', v_request.reference,
          'country_name', v_request.country_name,
          'jurisdiction_level', v_request.jurisdiction_level,
          'organisation_name', v_request.organisation_name,
          'review_status', 'PENDING_REVIEW',
          'submitted_at', v_request.submitted_at
        ),
        explanation = 'A verified participation request remains pending a governed human decision.',
        recommended_response = 'An authorised Platform Owner or support reviewer should assess the evidence and record a decision with rationale. Approval must remain separate from country provisioning.'
    where alert_fingerprint = v_fingerprint
      and alert_status = 'OPEN';
  end loop;

  update security_core.security_alert alert
  set alert_status = 'RESOLVED',
      acknowledged_at = now(),
      acknowledged_by = v_actor,
      resolution_rationale =
        'Automatically reconciled from protected evidence: the linked participation request is no longer PENDING_REVIEW.'
  where alert.alert_type = 'PARTICIPATION_REVIEW_PENDING'
    and alert.alert_status = 'OPEN'
    and not exists (
      select 1
      from public.aab_country_participation_requests request
      where request.id::text = alert.evidence_summary ->> 'request_id'
        and request.review_status = 'PENDING_REVIEW'
    );

  get diagnostics v_rows = row_count;
  v_resolved := v_resolved + v_rows;

  v_fingerprint := 'DAILY_ENTRY_BASELINE:' || to_char(current_date, 'YYYYMMDD');

  insert into security_core.security_alert(
    alert_fingerprint,
    alert_type,
    severity,
    confidence_status,
    title,
    explanation,
    evidence_summary,
    recommended_response,
    alert_status,
    acknowledged_at,
    acknowledged_by,
    resolution_rationale
  )
  values (
    v_fingerprint,
    'DAILY_ENTRY_BASELINE',
    'INFORMATION',
    'HIGH',
    'Daily protected-entry baseline',
    'A daily baseline was recorded for explainable comparison. This is not a threat determination.',
    jsonb_build_object(
      'allowed_entries',
      (select count(*) from platform.entry_audit_event
       where outcome_code = 'ALLOWED'
         and occurred_at > now() - interval '24 hours'),
      'window_hours',
      24
    ),
    'No action required. Retain for trend comparison.',
    'RESOLVED',
    now(),
    v_actor,
    'Informational baseline retained as historical evidence; no human response is required.'
  )
  on conflict (alert_fingerprint) do update
    set evidence_summary = excluded.evidence_summary,
        alert_status = case
          when security_core.security_alert.alert_status = 'OPEN'
            then 'RESOLVED'
          else security_core.security_alert.alert_status
        end,
        acknowledged_at = coalesce(
          security_core.security_alert.acknowledged_at,
          excluded.acknowledged_at
        ),
        acknowledged_by = coalesce(
          security_core.security_alert.acknowledged_by,
          excluded.acknowledged_by
        ),
        resolution_rationale = coalesce(
          security_core.security_alert.resolution_rationale,
          excluded.resolution_rationale
        );

  get diagnostics v_rows = row_count;

  update security_core.security_brain_run
  set completed_at = now(),
      rules_evaluated = 3,
      alerts_created = v_created,
      status = 'COMPLETED'
  where run_id = v_run;

  return jsonb_build_object(
    'ok', true,
    'run_id', v_run,
    'rules_evaluated', 3,
    'alerts_created_or_refreshed', v_created,
    'alerts_resolved', v_resolved,
    'open_alerts', (
      select count(*)
      from security_core.security_alert
      where alert_status = 'OPEN'
    ),
    'authority', 'ADVISORY_ONLY'
  );
exception
  when others then
    if v_run is not null then
      update security_core.security_brain_run
      set completed_at = now(), status = 'FAILED'
      where run_id = v_run;
    end if;
    raise;
end
$$;


ALTER FUNCTION "security_core"."api_run_security_brain"() OWNER TO "postgres";


