    CONSTRAINT "variety_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['DRAFT'::"text", 'ACTIVE'::"text", 'SUSPENDED'::"text", 'ARCHIVED'::"text"])))
